class VerifiedScheduledCompletionClient:
    """External completion-model boundary for successful artifact fixtures."""

    def create(self, **kwargs):
        payload = json.loads(kwargs["messages"][0]["content"][0]["text"])
        return {"content": [{"type": "text", "text": json.dumps({
            "status": "success", "answer": payload["final_answer"],
        })}]}


def test_market_quote_tool_summary_is_compact_and_not_search_leads() -> None:
    summary = _account_tool_summary(
        [
            ToolResult(
                "quote-1",
                "market_quote",
                "completed",
                {
                    "quotes": [
                        {
                            "symbol": "MSFT",
                            "name": "Microsoft Corp",
                            "price": 403.45,
                            "currency": "USD",
                            "exchange": "Nasdaq",
                        },
                        {
                            "symbol": "CRML",
                            "name": "Critical Metals Corp",
                            "price": 9.41,
                            "currency": "USD",
                            "exchange": "Nasdaq",
                        },
                    ]
                },
            )
        ]
    )

    assert summary is not None
    assert "Market prices from live quote data" in summary
    assert "MSFT (Microsoft Corp): $403.45" in summary
    assert "CRML (Critical Metals Corp): $9.41" in summary
    assert "Search leads I found" not in summary
    assert "Robinhood" not in summary


def test_email_attachment_summary_never_pastes_raw_extracted_document_text() -> None:
    summary = _account_tool_summary(
        [
            ToolResult(
                "attachment",
                "email_attachment_read",
                "completed",
                {
                    "filename": "appointment.pdf",
                    "mime_type": "application/pdf",
                    "size_bytes": 83918,
                    "artifact_path": "/tmp/appointment.pdf",
                    "text_preview": "NOTICE DATE\n07/03/2026\nACCOUNT NUMBER\n000000000000",
                },
            )
        ]
    )

    assert summary is not None
    assert "appointment.pdf" in summary
    assert "Text was extracted for analysis" in summary
    assert "NOTICE DATE" not in summary
    assert "ACCOUNT NUMBER" not in summary
    assert "/tmp/appointment.pdf" not in summary


def test_remember_chat_turn_does_not_restore_legacy_thread_on_save(tmp_path, monkeypatch) -> None:
    from nullion import chat_operator
    from nullion.runtime import bootstrap_persistent_runtime

    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    monkeypatch.setattr(
        chat_operator,
        "_get_chat_thread",
        lambda *args, **kwargs: (_ for _ in ()).throw(AssertionError("legacy thread restore must stay off save path")),
    )

    chat_operator._remember_chat_turn(
        runtime,
        chat_id="web:fast",
        user_message="Hi",
        assistant_reply="Hello.",
    )

    turns = runtime.store.list_conversation_chat_turns("web:fast", limit=5)
    assert turns[-1]["user"] == "Hi"
    assert turns[-1]["assistant"] == "Hello."


