def test_browser_answer_preservation_incomplete_blocker_preserves_current_request_target() -> None:
    draft_reply = ("I opened the page, but the browser interaction needed to finish the request did not complete, "
            "so I do not have verified result records from this run.")
    reply = sanitize_user_visible_reply(
        user_message="Check adult Citi Bike e-bike helmet requirements from the browser",
        reply=(
            "I opened the page, but the browser interaction needed to finish the request did not complete, "
            "so I do not have verified result records from this run."
        ),
        tool_results=[
            ToolResult("open-1", "browser_navigate", "completed", {"url": "https://example.test/bikes"}),
            ToolResult(
                "click-1",
                "browser_click_element",
                "failed",
                {"selector": "#submit"},
                error="required page state was not reached",
            ),
            ToolResult("extract-1", "browser_extract_text", "completed", {"text": "Generic category page"}),
        ],
    )

    assert reply == sanitize_user_visible_reply(user_message=None, reply=draft_reply, tool_results=[])


