def test_schema_followup_retry_uses_source_record_id_for_missing_email_read_id() -> None:
    from nullion import chat_operator

    invoked_arguments: list[dict[str, object]] = []

    class Registry:
        turn_tool_scope_decision = None

        def get_spec(self, tool_name: str) -> object:
            if tool_name == "email_read":
                return SimpleNamespace(
                    input_schema={"properties": {"id": {"type": "string"}, "provider_id": {"type": "string"}}},
                    requires_approval=False,
                    side_effect_class="read",
                )
            if tool_name == "email_search":
                return SimpleNamespace(
                    input_schema={"properties": {"query": {"type": "string"}}},
                    requires_approval=False,
                    side_effect_class="read",
                    continuation_tools=("email_read",),
                )
            raise KeyError(tool_name)

        def invoke(self, invocation: ToolInvocation) -> ToolResult:
            invoked_arguments.append(dict(invocation.arguments))
            return ToolResult(
                invocation.invocation_id,
                invocation.tool_name,
                "completed",
                {
                    "message": {
                        "id": invocation.arguments["id"],
                        "subject": "Re: lease",
                        "from": "Rosemarie",
                        "body": "Rosemarie has not replied with the signed lease yet.",
                    },
                    "provider_id": invocation.arguments.get("provider_id"),
                },
            )

        def list_tool_definitions(self) -> list[dict[str, object]]:
            return [
                {"name": "email_search", "continuation_tools": ["email_read"]},
                {"name": "email_read"},
            ]

    registry = Registry()
    initial_result = SimpleNamespace(
        turn_id="turn-email-followup",
        final_text="Please send me the message ID from the email search results.",
        tool_results=[
            ToolResult(
                "search-1",
                "email_search",
                "completed",
                {
                    "provider_id": "gmail",
                    "results": [
                        {
                            "id": "msg-rose-1",
                            "subject": "Re: lease",
                            "from": "Rosemarie",
                            "snippet": "Please send the signed lease.",
                        }
                    ],
                    "next_tool_for_body": "email_read",
                    "body_requires_tool": "email_read",
                },
            ),
            ToolResult(
                "read-1",
                "email_read",
                "failed",
                {"reason": "invalid_tool_arguments", "error": "missing required argument"},
                error="missing required argument",
            ),
        ],
        suspended_for_approval=False,
        approval_id=None,
        artifacts=[],
        thinking_text=None,
        reached_iteration_limit=False,
        raw_tool_payload_blocked=False,
    )

    def run_turn(history: list[dict[str, object]], retry_registry: object) -> object:
        system_text = "\n".join(
            str(block.get("text") or "")
            for message in history
            if message.get("role") == "system"
            for block in message.get("content", [])
            if isinstance(block, dict)
        )
        assert "Recovered evidence" in system_text
        assert "Rosemarie" in system_text
        return SimpleNamespace(
            turn_id="turn-email-followup-synth",
            final_text="Recommendation: escalate using the lease thread evidence; Rosemarie has not responded yet.",
            tool_results=[],
            suspended_for_approval=False,
            approval_id=None,
            artifacts=[],
            thinking_text=None,
            reached_iteration_limit=False,
            raw_tool_payload_blocked=False,
        )

    result, _retry_registry, retried = chat_operator._run_chat_turn_schema_followup_tool_retry(
        initial_result=initial_result,
        base_history=[],
        active_tool_registry=registry,
        evidence=None,
        run_turn=run_turn,
        principal_id="telegram_chat",
        user_message="Find the best escalation recipient.",
    )

    assert retried is True
    assert invoked_arguments == [{"id": "msg-rose-1", "provider_id": "gmail"}]
    assert "message ID" not in result.final_text
    assert "Recommendation:" in result.final_text


