@pytest.mark.parametrize("requested_read", [False, True])
def test_direct_open_url_respects_structured_read_request(monkeypatch: pytest.MonkeyPatch, requested_read: bool) -> None:
    from nullion import chat_operator
    from nullion.turn_context_policy import ScopedTurnToolRegistry, TurnToolEvidence, TurnToolScopeDecision

    registry = ToolRegistry()
    registry.register(
        ToolSpec(
            name="browser_navigate",
            description="browser_navigate",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            continuation_tools=("browser_extract_text",),
        ),
        lambda invocation: ToolResult(
            invocation.invocation_id,
            invocation.tool_name,
            "completed",
            {"url": invocation.arguments["url"]},
        ),
    )
    registry.register(
        ToolSpec(
            name="browser_extract_text",
            description="browser_extract_text",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
        ),
        lambda invocation: (_ for _ in ()).throw(AssertionError("open_url should not extract page text")),
    )
    scoped_registry = ScopedTurnToolRegistry(
        registry,
        evidence=TurnToolEvidence(has_url_target=True),
        tool_scope_decision=TurnToolScopeDecision(
            web_action="open_url",
            requested_tool_names=("browser_navigate", "browser_extract_text") if requested_read else ("browser_navigate",),
            required_tool_names=("browser_navigate",),
            valid=True,
        ),
    )
    calls: list[str] = []

    def fake_invoke(_store: object, invocation: ToolInvocation, *, registry: object) -> ToolResult:
        calls.append(invocation.tool_name)
        return registry.invoke(invocation)

    monkeypatch.setattr(chat_operator, "invoke_tool_with_boundary_policy", fake_invoke)

    result = chat_operator._run_open_url_tool_directly(
        runtime=SimpleNamespace(store=object()),
        registry=scoped_registry,
        base_registry=registry,
        principal_id="telegram_chat",
        turn_id="turn-open",
        user_message="Open this page and keep it open: https://example.test/cart",
    )

    if requested_read:
        assert result is None  # The normal agent must perform the requested read.
        assert calls == []
        return
    assert result is not None
    assert calls == ["browser_navigate"]
    assert [tool.tool_name for tool in result.tool_results] == ["browser_navigate"]
    assert result.final_text == "Opened https://example.test/cart."


