def test_artifact_paths_skip_file_write_sources_consumed_by_later_tools(tmp_path: Path) -> None:
    from nullion import chat_operator

    source = tmp_path / "stage_mixed_embedded_media_source.html"
    final_html = tmp_path / "stage_mixed_embedded_media.html"
    workbook = tmp_path / "stage_mixed_embedded_media.xlsx"
    for path in (source, final_html, workbook):
        path.write_text("artifact", encoding="utf-8")
    tool_results = [
        ToolResult("write-source", "file_write", "completed", {"path": str(source)}),
        ToolResult(
            "scope",
            "request_tool_scope",
            "completed",
            {"requested_artifact_extensions": [".html", ".xlsx"]},
        ),
        ToolResult("nav", "browser_navigate", "completed", {"url": source.as_uri()}),
        ToolResult("xlsx", "spreadsheet_create", "completed", {"artifact_path": str(workbook)}),
        ToolResult("write-final", "file_write", "completed", {"path": str(final_html)}),
    ]

    assert artifact_paths_from_tool_results(tool_results) == [str(workbook), str(final_html)]
    assert chat_operator._artifact_paths_from_tool_results(tool_results) == [str(workbook), str(final_html)]


def test_model_issue_recovery_probe_is_throttled(monkeypatch, tmp_path) -> None:
    from nullion import chat_operator, health_probes

    calls: list[object] = []

    def fake_probe_factory(model_client):  # noqa: ANN001
        def _probe():
            calls.append(model_client)
            return SimpleNamespace(ok=False)

        return _probe

    monkeypatch.setattr(health_probes, "make_model_api_probe", fake_probe_factory)
    monkeypatch.setenv("NULLION_MODEL_RECOVERY_PROBE_MIN_INTERVAL_SECONDS", "300")
    chat_operator._MODEL_ISSUE_RECOVERY_CHECKED_AT_BY_RUNTIME.clear()
