def test_chat_no_tool_model_memory_capture_is_default_background_enabled(monkeypatch) -> None:
    from nullion import chat_operator
    import nullion.builder_background as builder_background
    import nullion.builder_memory as builder_memory

    calls: list[str] = []
    events: list[str] = []

    def fake_capture(*args, **kwargs):  # noqa: ANN002, ANN003
        calls.append(kwargs.get("user_message", ""))
        return SimpleNamespace(written=0)

    def fake_record(*args, **kwargs):  # noqa: ANN002, ANN003
        events.append(kwargs.get("source", ""))

    monkeypatch.setenv("NULLION_MEMORY_ENABLED", "1")
    monkeypatch.delenv("NULLION_MEMORY_NO_TOOL_CAPTURE_ENABLED", raising=False)
    monkeypatch.setattr(builder_background, "schedule_builder_background_task", lambda _label, worker: (worker() or True))
    monkeypatch.setattr(builder_memory, "capture_turn_memory_claims_verified", fake_capture)
    monkeypatch.setattr(builder_memory, "record_turn_memory_capture_event", fake_record)
    runtime = SimpleNamespace(store=SimpleNamespace())
    orchestrator = SimpleNamespace(model_client=object())

    chat_operator._schedule_chat_turn_memory_capture(
        runtime,
        orchestrator,
        owner="workspace:workspace_admin",
        conversation_id="telegram:1",
        user_message="This ordinary chat should start background model memory capture.",
        assistant_reply="ok",
        tool_results=[],
    )

    assert calls == ["This ordinary chat should start background model memory capture."]
    assert events == ["chat_no_tool_turn"]
    assert guaranteed_user_visible_text(subject="", output={"text": "done"}, kind="task") == "done"


