def test_email_read_body_strips_invisible_tracking_and_uses_snippet_when_body_is_low_signal() -> None:
    from nullion.tools import _compact_gmail_message

    invisible_padding = ("CVS \u200c " * 700).strip()
    html_body = (
        "<html><head><style>body { line-height: normal !important; background-color: #fff; }</style></head>"
        f"<body>{invisible_padding}</body></html>"
    )
    encoded = base64.urlsafe_b64encode(html_body.encode("utf-8")).decode("ascii").rstrip("=")
    message = {
        "id": "msg-cvs",
        "threadId": "thread-cvs",
        "snippet": (
            "A new experience is on the way — your photos will transfer automatically as part of this update. "
            "Please use any credits by July 1."
        ),
        "payload": {
            "headers": [
                {"name": "Subject", "value": "Important update about your CVS Photo account"},
                {"name": "From", "value": "CVS <cvs@example.test>"},
                {"name": "Date", "value": "Sat, 30 May 2026 09:25:52 -0600"},
            ],
            "parts": [{"mimeType": "text/html", "body": {"data": encoded}}],
        },
        "labelIds": ["UNREAD", "IMPORTANT", "INBOX"],
    }

    compact = _compact_gmail_message(message, include_body=True)

    assert compact["body"] == message["snippet"]
    assert "\u200c" not in compact["body"]
    assert "line-height" not in compact["body"]


def test_email_read_exposes_hidden_html_anchor_links_without_raw_html() -> None:
    from nullion.tools import _compact_gmail_message

    text_body = "Saldo listo. Abre el portal."
    html_body = (
        "<html><body>"
        "<p>Saldo listo.</p>"
        "<a href=\"https://pay.example.test/checkout?token=abc123\">Abre el portal</a>"
        "</body></html>"
    )
    text_encoded = base64.urlsafe_b64encode(text_body.encode("utf-8")).decode("ascii").rstrip("=")
    html_encoded = base64.urlsafe_b64encode(html_body.encode("utf-8")).decode("ascii").rstrip("=")
    message = {
        "id": "msg-payment",
        "threadId": "thread-payment",
        "snippet": "Saldo listo. Abre el portal.",
        "payload": {
            "headers": [
                {"name": "Subject", "value": "Aviso"},
                {"name": "From", "value": "Portal <portal@example.test>"},
            ],
            "parts": [
                {"mimeType": "text/plain", "body": {"data": text_encoded}},
                {"mimeType": "text/html", "body": {"data": html_encoded}},
            ],
        },
    }

    compact = _compact_gmail_message(message, include_body=True)

    assert compact["links"] == [
        {
            "url": "https://pay.example.test/checkout?token=abc123",
            "text": "Abre el portal",
        }
    ]
    assert "href" not in compact["body"]
    assert "https://pay.example.test" not in compact["body"]


