def test_compacted_archive_output_preserves_deliverable_descriptors() -> None:
    from nullion.chat_operator import _compact_tool_output_for_context

    source_zip = "/tmp/Archive.zip"
    manifest_xlsx = "/tmp/stage_archive_manifest_rebuilt.xlsx"
    manifest_csv = "/tmp/stage_archive_manifest_rebuilt.csv"
    output = {
        "artifact_path": manifest_xlsx,
        "artifact_paths": [manifest_xlsx],
        "manifest_xlsx_path": manifest_xlsx,
        "manifest_csv_path": manifest_csv,
        "manifest_json_path": "/tmp/stage_archive_manifest_rebuilt.json",
        "manifest_artifact_paths": [
            manifest_xlsx,
            manifest_csv,
            "/tmp/stage_archive_manifest_rebuilt.json",
        ],
        "artifact_descriptors": [
            {"path": source_zip, "role": "source", "kind": "archive"},
            {"path": manifest_xlsx, "role": "deliverable", "kind": "archive_manifest"},
            {"path": manifest_csv, "role": "intermediate", "kind": "archive_manifest_sidecar"},
        ],
        "entries": [
            {"name": f"file_{index}.txt", "path": f"/tmp/extracted/file_{index}.txt", "bytes": index}
            for index in range(1000)
        ],
    }

    compact = _compact_tool_output_for_context("archive_extract", output)

    assert compact["deliverable_ready"] is True
    assert "manifest_json_path" not in compact
    assert "manifest_csv_path" not in compact
    assert "manifest_artifact_paths" not in compact
    assert "entries" not in compact
    assert compact["entries_sample"][0] == {"name": "file_0.txt", "bytes": 0}
    assert compact["entries_sample_truncated"] == {"shown": 20, "head": 12, "tail": 8, "total": 1000}
    assert compact["artifact_descriptors"] == output["artifact_descriptors"]
    assert compact["artifact_path"] == manifest_xlsx
    assert artifact_paths_from_tool_results(
        [ToolResult("extract", "archive_extract", "completed", compact)]
    ) == [manifest_xlsx]


