def test_chat_artifact_append_strips_unrequested_media_sidecars(tmp_path: Path) -> None:
    from nullion.chat_operator import _append_chat_artifacts_to_reply

    checkpoint = tmp_path / "runtime.db"
    artifact_root = tmp_path / "workspaces" / "workspace_admin" / "artifacts"
    artifact_root.mkdir(parents=True)
    manifest_xlsx = artifact_root / "stage_archive_manifest_rebuilt.xlsx"
    completion_csv = artifact_root / "tool_completion.csv"
    completion_json = artifact_root / "tool_completion.json"
    for path in (manifest_xlsx, completion_csv, completion_json):
        path.write_bytes(b"artifact")
    runtime = SimpleNamespace(checkpoint_path=checkpoint)
    tool_results = [
        ToolResult(
            "extract",
            "archive_extract",
            "completed",
            {
                "artifact_path": str(manifest_xlsx),
                "artifact_paths": [str(manifest_xlsx)],
                "artifact_descriptors": [
                    {"path": str(manifest_xlsx), "role": "deliverable", "kind": "archive_manifest"}
                ],
            },
        ),
        ToolResult("csv", "file_write", "completed", {"artifact_path": str(completion_csv), "path": str(completion_csv)}),
        ToolResult("json", "file_write", "completed", {"artifact_path": str(completion_json), "path": str(completion_json)}),
    ]
    bad_reply = (
        "Done.\n\n"
        f"MEDIA:{completion_csv}\n"
        f"MEDIA:{completion_json}\n"
        f"MEDIA:{manifest_xlsx}"
    )

    reply = _append_chat_artifacts_to_reply(
        runtime,
        reply=bad_reply,
        artifact_paths=[],
        prompt="create stage_archive_manifest_rebuilt.xlsx",
        principal_id="operator",
        tool_results=tool_results,
        required_attachment_extensions=(".xlsx", ".csv", ".json"),
        source_attachment_paths=set(),
    )

    assert str(manifest_xlsx) in reply
    assert str(completion_csv) not in reply
    assert str(completion_json) not in reply


