def test_chat_suppresses_stale_artifact_failure_after_parent_delivery(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from nullion import chat_operator
    from nullion.artifacts import artifact_root_for_runtime
    from nullion.runtime import bootstrap_persistent_runtime

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    monkeypatch.setenv("NULLION_HOME", str(tmp_path / "home"))
    monkeypatch.setenv("NULLION_WORKSPACE_STORAGE_ROOT", str(tmp_path / "data" / "workspaces"))
    principal_id = "telegram:test-chat"
    conversation_id = "telegram:test-chat"
    prompt = (
        "I need an excel for first 107 products on this link. Excel should have each product's "
        "picture, details, lizzie's note and price. https://lizziefortunato.com/collections/necklaces"
    )
    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    workbook = artifact_root_for_principal(principal_id) / "lizzie_fortunato_first_107_necklaces.xlsx"
    workbook.parent.mkdir(parents=True, exist_ok=True)
    workbook.write_bytes(b"PK\x03\x04xlsx")
    runtime.store.add_conversation_event(
        {
            "conversation_id": conversation_id,
            "event_type": "conversation.chat_turn",
            "created_at": "2026-06-08T18:24:29+00:00",
            "chat_id": "test-chat",
            "turn_id": "delivered-turn",
            "parent_turn_id": "previous-turn",
            "branch_id": "branch-test",
            "user_message": prompt,
            "assistant_reply": f"Done — attached the requested spreadsheet.\n\nMEDIA:{workbook}",
            "tool_results": [],
        }
    )

    suppress = chat_operator._should_suppress_stale_artifact_failure_reply(
        runtime,
        conversation_id=conversation_id,
        prompt=prompt,
        reply="I couldn't attach the requested file. The task is still open.",
        principal_id=principal_id,
        required_attachment_extensions=(".xlsx",),
        parent_turn_id="delivered-turn",
    )
    unrelated_parent = chat_operator._should_suppress_stale_artifact_failure_reply(
        runtime,
        conversation_id=conversation_id,
        prompt=prompt,
        reply="I couldn't attach the requested file. The task is still open.",
        principal_id=principal_id,
        required_attachment_extensions=(".xlsx",),
        parent_turn_id="other-turn",
    )

    assert suppress is True
    assert unrelated_parent is False


