def test_uploaded_spreadsheet_summary_does_not_echo_source_workbook(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from nullion.artifacts import artifact_root_for_runtime
    from nullion.chat_operator import _append_chat_artifacts_to_reply, _requested_attachment_extension
    from nullion.messaging_adapters import delivery_contract_for_turn, prepare_reply_for_platform_delivery
    from nullion.runtime import bootstrap_persistent_runtime

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    principal_id = "telegram:test-chat"
    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    source = artifact_root_for_principal(principal_id) / "cat_images.xlsx"
    source.parent.mkdir(parents=True, exist_ok=True)
    source.write_bytes(b"PK\x03\x04uploaded workbook")

    assert _requested_attachment_extension(
        "cat_images.xlsx, summarize it",
        source_attachment_names=("cat_images.xlsx",),
    ) is None

    reply = _append_chat_artifacts_to_reply(
        runtime,
        reply="The workbook contains a cat image tracker with three rows and two missing captions.",
        artifact_paths=[str(source)],
        prompt="cat_images.xlsx, summarize it",
        principal_id=principal_id,
        tool_results=[ToolResult("read", "file_read", "completed", {"path": str(source), "artifact_path": str(source)})],
        required_attachment_extensions=(),
        source_attachment_paths={str(source)},
    )
    contract = delivery_contract_for_turn("cat_images.xlsx, summarize it", reply=reply)
    delivery = prepare_reply_for_platform_delivery(reply, principal_id=principal_id, delivery_contract=contract)

    assert reply == "The workbook contains a cat image tracker with three rows and two missing captions."
    assert delivery.text == reply
