def test_terminal_stdout_discovery_artifacts_do_not_become_attachments(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from nullion.artifacts import artifact_root_for_principal
    from nullion.chat_operator import _append_chat_artifacts_to_reply
    from nullion.messaging_adapters import delivery_contract_for_turn, prepare_reply_for_platform_delivery
    from nullion.runtime import bootstrap_persistent_runtime

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    principal_id = "telegram:test-chat"
    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    artifact_root = artifact_root_for_principal(principal_id)
    artifact_root.mkdir(parents=True, exist_ok=True)
    listed_artifacts = [
        artifact_root / "existing-one.pdf",
        artifact_root / "existing-two.pdf",
        artifact_root / "existing-three.pdf",
    ]
    for path in listed_artifacts:
        path.write_bytes(b"%PDF-1.4\n")

    stdout = "\n".join(str(path) for path in listed_artifacts)
    reply = "Found 3 PDF files:\n\n```text\nexisting-one.pdf\nexisting-two.pdf\nexisting-three.pdf\n```"
    appended = _append_chat_artifacts_to_reply(
        runtime,
        reply=reply,
        artifact_paths=(),
        prompt="execute the script and return the output",
        principal_id=principal_id,
        tool_results=[
            ToolResult(
                "terminal",
                "terminal_exec",
                "completed",
                {
                    "stdout": stdout,
                    "stderr": "",
                    "exit_code": 0,
                    "artifact_paths": [str(path) for path in listed_artifacts],
                },
            )
        ],
        required_attachment_extensions=(),
    )
    contract = delivery_contract_for_turn("execute the script and return the output", reply=appended)
    delivery = prepare_reply_for_platform_delivery(appended, principal_id=principal_id, delivery_contract=contract)

    assert "MEDIA:" not in appended
    assert all(path.name in delivery.text for path in listed_artifacts)
    assert delivery.attachments == ()


