def test_terminal_exec_filesystem_json_output_is_summarized_for_cleanup_request() -> None:
    from nullion.chat_operator import _sanitize_chat_reply

    sanitized = _sanitize_chat_reply(
        prompt="find files that i can delete from my computer that are cached files",
        reply="",
        tool_results=[
            ToolResult(
                "terminal",
                "terminal_exec",
                "completed",
                {
                    "stdout": json.dumps(
                        [
                            {
                                "path": "/Users/example/.cache",
                                "count": 27092,
                                "size_bytes": 1782896047,
                            },
                            {
                                "path": "/Users/example/Library/Caches",
                                "count": 23463,
                                "size_bytes": 1061665951,
                            },
                            {
                                "path": "/Users/example/Library/Application Support",
                                "count": 16328,
                                "size_bytes": 21254764372,
                            },
                            {
                                "path": "/Users/example/.Trash",
                                "count": 0,
                                "size_bytes": 0,
                            },
                        ],
                        indent=2,
                    ),
                    "stderr": "",
                    "exit_code": 0,
                },
            ),
            ToolResult(
                "terminal",
                "terminal_exec",
                "completed",
                {
                    "stdout": json.dumps(
                        [
                            {
                                "path": "/Users/example/.cache",
                                "count": 27095,
                                "size_bytes": 1782896047,
                            }
                        ],
                        indent=2,
                    ),
                    "stderr": "",
                    "exit_code": 0,
                },
            ),
        ],
    )

    assert "I found concrete cleanup candidates" in sanitized
    assert "No files were deleted" in sanitized
    assert "Best low-risk cache folders" in sanitized
    assert "Review before deleting" in sanitized
    assert "`~/.cache`" in sanitized
    assert "1.8 GB" in sanitized
    assert "27,095 items" in sanitized
    assert "`~/Library/Caches`" in sanitized
    assert "`~/Library/Application Support`" in sanitized
    assert "21 GB" in sanitized
    assert "app data; do not blanket-delete" in sanitized
    assert "`~/.Trash`" not in sanitized
    assert '"path"' not in sanitized
    assert "```text" not in sanitized


