def test_context_followup_output_filename_extension_overrides_source_format(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from nullion import chat_operator
    from nullion.artifacts import artifact_root_for_principal
    from nullion.runtime import bootstrap_persistent_runtime

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    monkeypatch.setenv("NULLION_HOME", str(tmp_path / "home"))
    principal_id = "telegram:test-chat"
    conversation_id = "telegram:test-chat"
    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    artifact_root = artifact_root_for_principal(principal_id)
    artifact_root.mkdir(parents=True, exist_ok=True)
    source_csv = artifact_root / "stage_followup_source_values.csv"
    source_csv.write_text("Region,Value\nNorth,12\n", encoding="utf-8")
    runtime.store.add_conversation_event(
        {
            "conversation_id": conversation_id,
            "event_type": "conversation.chat_turn",
            "assistant_reply": f"Done.\nMEDIA:{source_csv}",
            "tool_results": [
                {
                    "tool_name": "file_write",
                    "status": "completed",
                    "output": {"path": str(source_csv), "artifact_path": str(source_csv)},
                }
            ],
        }
    )
    conversation_result = SimpleNamespace(
        turn=SimpleNamespace(parent_turn_id="turn-source"),
        task_frame_continuation=None,
    )

    xlsx_prompt = (
        "Using the CSV you just created in this same chat, create an XLSX workbook named "
        "stage_followup_reuse_values.xlsx with the same four rows and a Summary sheet containing the total. "
        "Attach only the XLSX."
    )

    assert chat_operator._prefer_new_output_filename_extensions_from_recent_artifacts(
        runtime,
        conversation_id=conversation_id,
        conversation_result=None,
        prompt=xlsx_prompt,
        requested_extensions=(".csv",),
    ) == (".xlsx",)
    assert chat_operator._inferred_scope_extensions_from_recent_artifacts(
        runtime,
        conversation_id=conversation_id,
        conversation_result=None,
        prompt=xlsx_prompt,
        explicit_requested_extensions=(".csv",),
    ) == (".xlsx",)

    requested_xlsx = artifact_root / "stage_followup_reuse_values.xlsx"
    requested_xlsx.write_bytes(b"xlsx")
    runtime.store.add_conversation_event(
        {
            "conversation_id": conversation_id,
            "event_type": "conversation.chat_turn",
            "assistant_reply": f"Done.\nMEDIA:{requested_xlsx}",
            "tool_results": [
                {
                    "tool_name": "spreadsheet_create",
                    "status": "completed",
                    "output": {
                        "path": str(requested_xlsx),
                        "artifact_path": str(requested_xlsx),
                        "artifact_descriptors": [
                            {
                                "path": str(requested_xlsx),
                                "extension": ".xlsx",
                                "role": "deliverable",
                            }
                        ],
                    },
                }
            ],
        }
    )
    pdf_prompt = (
        "Using the workbook you just created, create a PDF named stage_followup_reuse_summary.pdf that states "
        "the total and the top region. Attach only the PDF."
    )

    assert chat_operator._prefer_new_output_filename_extensions_from_recent_artifacts(
        runtime,
        conversation_id=conversation_id,
        conversation_result=conversation_result,
        prompt=pdf_prompt,
        requested_extensions=(),
    ) == (".pdf",)


