def test_orchestrator_required_artifacts_wait_for_every_extension(tmp_path: Path) -> None:
    from nullion.agent_orchestrator import (
        _completed_required_artifact_paths_for_turn,
        _completed_required_artifact_reply,
    )

    xlsx = tmp_path / "pack.xlsx"
    csv = tmp_path / "pack.csv"
    pdf = tmp_path / "pack.pdf"
    for path in (xlsx, csv, pdf):
        path.write_bytes(b"artifact")

    state = {"tool_flow_context": {"required_artifact_extensions": [".xlsx", ".csv", ".pdf"]}}

    assert _completed_required_artifact_paths_for_turn(state, [str(xlsx), str(csv)]) == ()
    completed = _completed_required_artifact_paths_for_turn(state, [str(xlsx), str(csv), str(pdf)])

    assert completed == (str(xlsx), str(csv), str(pdf))
    reply = _completed_required_artifact_reply(completed)
    assert "XLSX workbook" in reply
    assert "CSV" in reply
    assert "PDF" in reply
    assert reply.count("MEDIA:") == 3


