def test_email_send_guard_rejects_plain_office_replacement_when_recent_media_artifact_exists(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from nullion.agent_orchestrator import _email_attachment_artifact_preflight_guard_result
    from nullion.artifacts import artifact_root_for_principal
    from nullion.runtime import bootstrap_persistent_runtime

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    monkeypatch.setenv("NULLION_HOME", str(tmp_path / "home"))
    conversation_id = "web:stage-live-email-media"
    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    artifact_root = artifact_root_for_principal(conversation_id)
    artifact_root.mkdir(parents=True, exist_ok=True)
    media_workbook = artifact_root / "stage_multi_tool_qa_media.xlsx"
    plain_workbook = artifact_root / "stage_multi_tool_qa_email_workbook.xlsx"
    pdf = artifact_root / "summary.pdf"
    with zipfile.ZipFile(media_workbook, "w") as package:
        package.writestr("xl/workbook.xml", "<workbook/>")
        package.writestr("xl/media/image1.png", b"\x89PNG\r\n\x1a\n")
    with zipfile.ZipFile(plain_workbook, "w") as package:
        package.writestr("xl/workbook.xml", "<workbook/>")
    pdf.write_bytes(b"%PDF-1.4\n%%EOF")
    runtime.store.add_conversation_event(
        {
            "conversation_id": conversation_id,
            "event_type": "conversation.chat_turn",
            "artifacts": [{"path": str(media_workbook)}],
            "tool_results": [
                {
                    "tool_name": "spreadsheet_create",
                    "status": "completed",
                    "output": {
                        "artifact_path": str(media_workbook),
                        "artifact_descriptors": [{"path": str(media_workbook), "role": "deliverable"}],
                    },
                }
            ],
        }
    )

    result = _email_attachment_artifact_preflight_guard_result(
        {
            "conversation_id": conversation_id,
            "runtime_store": runtime.store,
            "tool_results": [],
        },
        invocation=ToolInvocation(
            "send",
            "email_send",
            conversation_id,
            {"to": "recipient@example.com", "attachment_paths": [str(pdf), str(plain_workbook)]},
        ),
        artifacts=[str(pdf), str(plain_workbook)],
    )

    assert result is not None
    assert result.status == "failed"
    assert result.output["reason"] == "email_attachment_requires_embedded_media"
    assert str(media_workbook) in result.output["replacement_attachment_paths"]
    assert str(plain_workbook) not in result.output["replacement_attachment_paths"]


