    docx = artifact_root / "booklet.docx"
    html = artifact_root / "edition.html"
    for path in (pdf, pptx, docx):
        path.write_bytes(b"artifact")
    html.write_text(
        "<!doctype html><html><head><title>Artifact</title></head><body><main>artifact package</main></body></html>",
        encoding="utf-8",
    )
    tool_results = [
        ToolResult("pdf", "pdf_create", "completed", {"artifact_path": str(pdf)}),
        ToolResult("pptx", "presentation_create", "completed", {"artifact_path": str(pptx)}),
        ToolResult("docx", "document_create", "completed", {"artifact_path": str(docx)}),
        ToolResult("html", "file_write", "completed", {"path": str(html)}),
    ]

    rendered = _enforce_chat_response_fulfillment(
        runtime,
        conversation_id="telegram:test-chat",
        prompt="Create DOCX, PDF, PPTX, and HTML.",
        reply="Done.",
        tool_results=tool_results,
        artifact_paths=[str(pdf), str(pptx), str(docx), str(html)],
        principal_id=principal_id,
        required_attachment_extensions=(".docx", ".pdf", ".pptx", ".html"),
    )

    assert f"MEDIA:{docx}" in rendered
    assert f"MEDIA:{pdf}" in rendered
    assert f"MEDIA:{pptx}" in rendered
    assert f"MEDIA:{html}" in rendered


