def test_chat_preserves_structured_final_reply_when_attaching_artifacts(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from nullion.artifacts import artifact_root_for_principal
    from nullion.chat_operator import _append_chat_artifacts_to_reply
    from nullion.messaging_adapters import delivery_contract_for_turn, prepare_reply_for_platform_delivery
    from nullion.runtime import bootstrap_persistent_runtime

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    principal_id = "telegram:structured-artifacts"
    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    artifact_root = artifact_root_for_principal(principal_id)
    report = artifact_root / "reliability_brief.pdf"
    workbook = artifact_root / "reliability_brief.xlsx"
    report.parent.mkdir(parents=True, exist_ok=True)
    report.write_bytes(b"%PDF-1.7\nstructured report")
    workbook.write_bytes(b"PK\x03\x04structured workbook")
    tool_results = [
        ToolResult("pdf", "pdf_create", "completed", {"artifact_path": str(report)}),
        ToolResult("sheet", "spreadsheet_create", "completed", {"artifact_path": str(workbook)}),
    ]
    visible = "\n".join(
        [
            "Outcome: The workflow completed with one recoverable extraction failure.",
            "Tools exercised: Browser, weather, connector metadata, PDF, and spreadsheet creation.",
            "Artifacts: The PDF and workbook are attached.",
            "Fallbacks: Browser extraction failed once and image recovery supplied the visual evidence.",
            "Next: Review the attached files before promoting the scenario.",
        ]
    )

    reply = _append_chat_artifacts_to_reply(
        runtime,
        reply=visible,
        artifact_paths=(),
        prompt="Create a structured report and workbook from verified runtime evidence.",
        principal_id=principal_id,
        tool_results=tool_results,
        required_attachment_extensions=(".pdf", ".xlsx"),
    )
    contract = delivery_contract_for_turn(
        "Create a structured report and workbook from verified runtime evidence.",
        reply=reply,
        required_attachment_extensions=(".pdf", ".xlsx"),
    )
    delivery = prepare_reply_for_platform_delivery(reply, principal_id=principal_id, delivery_contract=contract)

    assert reply.startswith(visible)
    assert "Done — attached the requested files." not in reply
    assert f"MEDIA:{report}" in reply
    assert f"MEDIA:{workbook}" in reply
    assert delivery.text == visible
    assert delivery.attachments == (report, workbook)


