def test_conversation_history_tool_searches_saved_turns_beyond_visible_window(tmp_path: Path) -> None:
    from nullion.conversation_history_tools import CHAT_HISTORY_SEARCH_TOOL_NAME, with_conversation_history_tool
    from nullion.runtime import bootstrap_persistent_runtime

    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    conversation_id = "telegram:test-chat"
    for index in range(12):
        runtime.store.add_conversation_event(
            {
                "conversation_id": conversation_id,
                "event_type": "conversation.chat_turn",
                "created_at": datetime(2026, 5, 25, 12, index, tzinfo=UTC).isoformat(),
                "turn_id": f"turn-{index}",
                "user_message": (
                    "NJ Transit train 372 departs at 1:14 PM"
                    if index == 1
                    else f"ordinary saved turn {index}"
                ),
                "assistant_reply": (
                    "It reaches New York Penn Station at 2:08 PM."
                    if index == 1
                    else f"ordinary reply {index}"
                ),
            }
        )
    registry = with_conversation_history_tool(
        ToolRegistry(),
        runtime=runtime,
        conversation_id=conversation_id,
    )

    assert CHAT_HISTORY_SEARCH_TOOL_NAME in {spec.name for spec in registry.list_specs()}
    result = registry.invoke(
        ToolInvocation(
            invocation_id="history",
            tool_name=CHAT_HISTORY_SEARCH_TOOL_NAME,
            principal_id="test",
            arguments={"query": "NJ Transit train 372", "limit": 3},
        )
    )

    assert result.status == "completed"
    assert result.output["searched_turn_count"] == 12
    assert result.output["match_count"] >= 1
    rendered_matches = "\n".join(
        f"{match.get('user_message', '')}\n{match.get('assistant_reply', '')}"
        for match in result.output["matches"]
    )
    assert "NJ Transit train 372" in rendered_matches
    assert "2:08 PM" in rendered_matches


def test_conversation_history_wrapper_does_not_list_registry_on_hot_path() -> None:
    from nullion.conversation_history_tools import CHAT_HISTORY_SEARCH_TOOL_NAME, with_conversation_history_tool

    class ExplodingRegistry:
        def list_specs(self):  # pragma: no cover - must not be called
            raise AssertionError("history wrapper setup must not list registry specs")

        def list_tool_definitions(self):  # pragma: no cover - must not be called
            raise AssertionError("history wrapper setup must not list registry definitions")

        def get_spec(self, name: str):  # pragma: no cover - delegated tools are irrelevant here
            raise KeyError(name)

    registry = with_conversation_history_tool(
        ExplodingRegistry(),
        runtime=SimpleNamespace(store=object()),
        conversation_id="web:history-hot-path",
    )

    assert registry.get_spec(CHAT_HISTORY_SEARCH_TOOL_NAME).name == CHAT_HISTORY_SEARCH_TOOL_NAME


def test_conversation_history_tool_filters_events_by_workspace_metadata(
    tmp_path: Path,
    monkeypatch,
) -> None:
    from nullion.conversation_history_tools import CHAT_HISTORY_SEARCH_TOOL_NAME, with_conversation_history_tool
    from nullion.runtime import bootstrap_persistent_runtime

    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    conversation_id = "telegram:test-chat"
    monkeypatch.setattr(
        "nullion.connections.workspace_id_for_principal",
        lambda principal: "workspace_alpha",
    )
    runtime.store.add_conversation_event(
        {
            "conversation_id": conversation_id,
            "workspace_id": "workspace_beta",
            "event_type": "conversation.chat_turn",
            "created_at": datetime(2026, 5, 25, 12, 1, tzinfo=UTC).isoformat(),
            "turn_id": "turn-other-workspace",
            "user_message": "Find the confidential orchid record",
            "assistant_reply": "The other workspace record is O-918.",
        }
    )
    runtime.store.add_conversation_event(
        {
            "conversation_id": conversation_id,
            "workspace_id": "workspace_alpha",
            "event_type": "conversation.chat_turn",
            "created_at": datetime(2026, 5, 25, 12, 2, tzinfo=UTC).isoformat(),
            "turn_id": "turn-current-workspace",
            "user_message": "Find the public cedar record",
            "assistant_reply": "The current workspace record is C-204.",
        }
    )
    registry = with_conversation_history_tool(
        ToolRegistry(),
        runtime=runtime,
        conversation_id=conversation_id,
    )

    beta_result = registry.invoke(
        ToolInvocation(
            invocation_id="history-beta",
            tool_name=CHAT_HISTORY_SEARCH_TOOL_NAME,
            principal_id="test",
            arguments={"query": "orchid O-918", "limit": 5},
        )
    )
    alpha_result = registry.invoke(
        ToolInvocation(
            invocation_id="history-alpha",
            tool_name=CHAT_HISTORY_SEARCH_TOOL_NAME,
            principal_id="test",
            arguments={"query": "cedar C-204", "limit": 5},
        )
    )

    assert beta_result.status == "completed"
    assert beta_result.output["workspace_id"] == "workspace_alpha"
    assert beta_result.output["searched_turn_count"] == 1
    assert beta_result.output["matches"] == []
    assert alpha_result.output["matches"][0]["turn_id"] == "turn-current-workspace"
    assert alpha_result.output["matches"][0]["workspace_id"] == "workspace_alpha"


def test_conversation_history_tool_searches_workspace_across_conversations(
    tmp_path: Path,
    monkeypatch,
) -> None:
    from nullion.conversation_history_tools import CHAT_HISTORY_SEARCH_TOOL_NAME, with_conversation_history_tool
    from nullion.runtime import bootstrap_persistent_runtime

    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")

    def workspace_for(principal: object) -> str:
        text = str(principal or "")
        if text in {"telegram:current-chat", "web:other-chat"}:
            return "workspace_alpha"
        return "workspace_beta"

    monkeypatch.setattr("nullion.connections.workspace_id_for_principal", workspace_for)
    runtime.store.add_conversation_event(
        {
            "conversation_id": "web:other-chat",
            "event_type": "conversation.chat_turn",
            "created_at": datetime(2026, 5, 25, 12, 2, tzinfo=UTC).isoformat(),
            "turn_id": "turn-same-workspace-other-surface",
            "user_message": "Save the cross workspace-safe clue",
            "assistant_reply": "The shared workspace record is CROSS-777.",
        }
    )
    runtime.store.add_conversation_event(
        {
            "conversation_id": "telegram:other-workspace",
            "event_type": "conversation.chat_turn",
            "created_at": datetime(2026, 5, 25, 12, 3, tzinfo=UTC).isoformat(),
            "turn_id": "turn-other-workspace",
            "user_message": "Save the external clue",
            "assistant_reply": "The private record is LEAK-999.",
        }
    )
    registry = with_conversation_history_tool(
        ToolRegistry(),
        runtime=runtime,
        conversation_id="telegram:current-chat",
    )

    same_workspace = registry.invoke(
        ToolInvocation(
            invocation_id="history-same-workspace",
            tool_name=CHAT_HISTORY_SEARCH_TOOL_NAME,
            principal_id="test",
            arguments={"query": "CROSS-777", "limit": 5},
        )
    )
    other_workspace = registry.invoke(
        ToolInvocation(
            invocation_id="history-other-workspace",
            tool_name=CHAT_HISTORY_SEARCH_TOOL_NAME,
            principal_id="test",
            arguments={"query": "LEAK-999", "limit": 5},
        )
    )

    assert same_workspace.status == "completed"
    assert same_workspace.output["workspace_id"] == "workspace_alpha"
    assert same_workspace.output["searched_scope"] == "full_workspace_after_reset"
    assert same_workspace.output["matches"][0]["conversation_id"] == "web:other-chat"
    assert same_workspace.output["matches"][0]["turn_id"] == "turn-same-workspace-other-surface"
    assert other_workspace.output["matches"] == []


def test_conversation_history_query_searches_past_recent_scan_window(tmp_path: Path) -> None:
    from nullion.conversation_history_tools import CHAT_HISTORY_SEARCH_TOOL_NAME, with_conversation_history_tool
    from nullion.runtime import bootstrap_persistent_runtime

    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    conversation_id = "telegram:test-chat"
    runtime.store.add_conversation_event(
        {
            "conversation_id": conversation_id,
            "event_type": "conversation.chat_turn",
            "created_at": datetime(2026, 5, 25, 15, 45, tzinfo=UTC).isoformat(),
            "turn_id": "turn-original-target-4821",
            "user_message": "Please analyze the attached file(s).",
            "assistant_reply": (
                "The uploaded item is catalog target 4821 with the blue label variant."
            ),
        }
    )
    for index in range(260):
        runtime.store.add_conversation_event(
            {
                "conversation_id": conversation_id,
                "event_type": "conversation.chat_turn",
                "created_at": datetime(2026, 5, 26, 12, min(index, 59), tzinfo=UTC).isoformat(),
                "turn_id": f"turn-filler-{index}",
                "user_message": f"ordinary later saved turn {index}",
                "assistant_reply": f"ordinary later reply {index}",
            }
        )
    registry = with_conversation_history_tool(
        ToolRegistry(),
        runtime=runtime,
        conversation_id=conversation_id,
    )

    result = registry.invoke(
        ToolInvocation(
            invocation_id="history",
            tool_name=CHAT_HISTORY_SEARCH_TOOL_NAME,
            principal_id="test",
            arguments={"query": "catalog target 4821", "limit": 5},
        )
    )

    assert result.status == "completed"
    assert result.output["searched_scope"] == "full_workspace_after_reset"
    assert result.output["searched_turn_count"] == 261
    assert result.output["fallback_to_recent"] is False
    rendered_matches = "\n".join(
        f"{match.get('turn_id', '')}\n{match.get('user_message', '')}\n{match.get('assistant_reply', '')}"
        for match in result.output["matches"]
    )
    assert "turn-original-target-4821" in rendered_matches
    assert "catalog target 4821" in rendered_matches


