def test_conversation_history_structured_match_omits_unrelated_context_tool_evidence(
    tmp_path: Path,
) -> None:
    from nullion.conversation_history_tools import CHAT_HISTORY_SEARCH_TOOL_NAME, with_conversation_history_tool
    from nullion.runtime import bootstrap_persistent_runtime

    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    conversation_id = "telegram:test-chat"
    runtime.store.add_conversation_event(
        {
            "conversation_id": conversation_id,
            "event_type": "conversation.chat_turn",
            "created_at": datetime(2026, 5, 25, 12, 0, tzinfo=UTC).isoformat(),
            "turn_id": "turn-voice",
            "user_message": "Please analyze the attached file(s).",
            "assistant_reply": "The audio transcription is: what is going on?",
            "tool_results": [
                {
                    "tool_name": "audio_transcribe",
                    "status": "completed",
                    "output": {"path": "telegram-voice.ogg", "text": "what is going on?"},
                }
            ],
        }
    )
    runtime.store.add_conversation_event(
        {
            "conversation_id": conversation_id,
            "event_type": "conversation.chat_turn",
            "created_at": datetime(2026, 5, 25, 12, 5, tzinfo=UTC).isoformat(),
            "turn_id": "turn-pr-target",
            "user_message": "[Scheduled task delivery context] task=Check PR #29 merge readiness; channel=telegram; artifacts=none",
            "assistant_reply": (
                "SCHEDULED TASK: Check PR #29 merge readiness. "
                "PR #29 (`sample-team/sample-app`) is not ready to merge yet."
            ),
        }
    )
    runtime.store.add_conversation_event(
        {
            "conversation_id": conversation_id,
            "event_type": "conversation.chat_turn",
            "created_at": datetime(2026, 5, 25, 12, 6, tzinfo=UTC).isoformat(),
            "turn_id": "turn-pr-history-assisted",
            "user_message": "PR?",
            "assistant_reply": "I found the PR target from saved context: PR #29 in `sample-team/sample-app`.",
            "tool_results": [
                {
                    "tool_name": "chat_history_search",
                    "status": "completed",
                    "output": {"message": "Found saved context."},
                },
                {
                    "tool_name": "audio_transcribe",
                    "status": "completed",
                    "output": {"path": "telegram-voice.ogg", "text": "what is going on?"},
                },
            ],
        }
    )

    registry = with_conversation_history_tool(
        ToolRegistry(),
        runtime=runtime,
        conversation_id=conversation_id,
    )
    result = registry.invoke(
        ToolInvocation(
            invocation_id="history-1",
            tool_name=CHAT_HISTORY_SEARCH_TOOL_NAME,
            principal_id="test",
            arguments={"query": "PR #29 merge readiness nullion", "limit": 5},
        )
    )

    assert result.status == "completed"
    assert {match["turn_id"] for match in result.output["matches"]} == {
        "turn-pr-target",
        "turn-pr-history-assisted",
    }
    encoded = json.dumps(result.output, sort_keys=True)
    assert '"type": "scheduled_task"' in encoded
    assert "github.com" not in encoded
    assert "audio_transcribe" not in encoded


def test_conversation_history_tool_reads_unified_chat_store_when_runtime_turn_missing(
    tmp_path: Path,
    monkeypatch,
) -> None:
    from nullion.conversation_history_tools import CHAT_HISTORY_SEARCH_TOOL_NAME, with_conversation_history_tool
    from nullion.chat_store import ChatStore
    from nullion.runtime import bootstrap_persistent_runtime

    conversation_id = "telegram:test-chat"
    other_workspace_conversation_id = "telegram:other-workspace"
    same_workspace_conversation_id = "web:same-workspace-chat"

    def workspace_for(principal: object) -> str:
        text = str(principal or "")
        if text in {conversation_id, same_workspace_conversation_id}:
            return "workspace_alpha"
        return "workspace_beta"

    monkeypatch.setattr("nullion.connections.workspace_id_for_principal", workspace_for)
    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    chat_history = ChatStore(
        db_path=tmp_path / "chat_history.db",
        key_path=tmp_path / "chat_history.key",
    )
    chat_history.save_message(
        same_workspace_conversation_id,
        "user",
        "What was that cross-surface record from the saved chat?",
        channel=same_workspace_conversation_id,
        channel_label="Web",
    )
    chat_history.save_message(
        same_workspace_conversation_id,
        "bot",
        "The same workspace cross-surface record is CROSS-777.",
        channel=same_workspace_conversation_id,
        channel_label="Web",
    )
    chat_history.save_message(
        other_workspace_conversation_id,
        "user",
        "Save the private other-workspace record",
        channel=other_workspace_conversation_id,
        channel_label="Telegram",
    )
    chat_history.save_message(
        other_workspace_conversation_id,
        "bot",
        "The private other-workspace record is LEAK-999.",
        channel=other_workspace_conversation_id,
        channel_label="Telegram",
    )
    chat_history.save_message(
        conversation_id,
        "user",
        "When does the NJ Transit train from Princeton get to NYC?",
        channel=conversation_id,
        channel_label="Telegram",
    )
    chat_history.save_message(
        conversation_id,
        "bot",
        "I need the exact station to narrow it down.",
        channel=conversation_id,
        channel_label="Telegram",
    )
    chat_history.save_message(
        conversation_id,
        "user",
        "Princeton junction to nyc penn statuon",
        channel=conversation_id,
        channel_label="Telegram",
    )
    chat_history.save_message(
        conversation_id,
        "bot",
        "From Princeton Junction to New York Penn: 2:11 PM arrives 3:34 PM, Northeast Corridor #7840.",
        channel=conversation_id,
        channel_label="Telegram",
    )

    registry = with_conversation_history_tool(
        ToolRegistry(),
        runtime=runtime,
        conversation_id=conversation_id,
    )
    result = registry.invoke(
        ToolInvocation(
            invocation_id="history",
            tool_name=CHAT_HISTORY_SEARCH_TOOL_NAME,
            principal_id="test",
            arguments={"query": "that nj transit train we were talking about", "limit": 10},
        )
    )

    rendered_matches = "\n".join(
        f"{match.get('user_message', '')}\n{match.get('assistant_reply', '')}"
        for match in result.output["matches"]
    )
    assert result.status == "completed"
    assert result.output["searched_turn_count"] == 3
    assert "Princeton Junction" in rendered_matches
    assert "#7840" in rendered_matches

    cross_result = registry.invoke(
        ToolInvocation(
            invocation_id="history-cross",
            tool_name=CHAT_HISTORY_SEARCH_TOOL_NAME,
            principal_id="test",
            arguments={"query": "CROSS-777", "limit": 10},
        )
    )
    leak_result = registry.invoke(
        ToolInvocation(
            invocation_id="history-leak",
            tool_name=CHAT_HISTORY_SEARCH_TOOL_NAME,
            principal_id="test",
            arguments={"query": "LEAK-999", "limit": 10},
        )
    )

    assert cross_result.output["matches"][0]["conversation_id"] == same_workspace_conversation_id
    assert cross_result.output["matches"][0]["workspace_id"] == "workspace_alpha"
    assert leak_result.output["matches"] == []


