def test_chat_rejects_pdf_pending_text_sidecar_for_pdf_request(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from nullion.artifacts import artifact_root_for_principal
    from nullion.attachment_format_graph import plan_attachment_format
    from nullion.chat_operator import _append_chat_artifacts_to_reply, _requested_attachment_extension
    from nullion.messaging_adapters import delivery_contract_for_turn, prepare_reply_for_platform_delivery
    from nullion.runtime import bootstrap_persistent_runtime
    from nullion.turn_context_policy import build_turn_tool_evidence, scoped_turn_tool_registry
    from nullion.tools import create_plugin_tool_registry

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    monkeypatch.setenv("NULLION_FILE_ACCESS_ENABLED", "true")
    principal_id = "telegram:test-chat"
    prompt = "Make a professional looking pdf with images and links and description and distance from our location"
    runtime = bootstrap_persistent_runtime(tmp_path / "runtime-pdf-sidecar.db")
    artifact_root = artifact_root_for_principal(principal_id)
    sidecar = artifact_root / "indoor_activities_pdf_pending.txt"
    sidecar.parent.mkdir(parents=True, exist_ok=True)
    sidecar.write_text(
        "Pending professional PDF creation for indoor activities.\n\nCannot yet generate the requested researched PDF.",
        encoding="utf-8",
    )
    tool_result = ToolResult("write", "file_write", "completed", {"path": str(sidecar)})

    # The bare word "pdf" is not structural routing evidence. This test
    # simulates a typed planner/model contract that already verified .pdf.
    assert plan_attachment_format(prompt).extension is None
    assert _requested_attachment_extension(prompt) is None
    evidence = build_turn_tool_evidence(
        user_message=prompt,
        conversation_result=None,
        requested_extensions=(".pdf",),
    )
    base_registry = create_plugin_tool_registry(allowed_roots=[artifact_root])
    scoped_registry = scoped_turn_tool_registry(base_registry, evidence=evidence)
    scoped_tool_names = {
        item["name"]
        for item in scoped_registry.list_tool_definitions()
    }
    assert "pdf_create" in scoped_tool_names
    assert "file_write" not in scoped_tool_names
    assert evidence.requested_extensions == (".pdf",)

    reply = _append_chat_artifacts_to_reply(
        runtime,
        reply=f"Done — attached the requested text file.\n\nMEDIA:{sidecar}",
        artifact_paths=(),
        prompt=prompt,
        principal_id=principal_id,
        tool_results=[tool_result],
        required_attachment_extensions=(".pdf",),
    )
    contract = delivery_contract_for_turn(prompt, reply=reply, required_attachment_extensions=(".pdf",))
    delivery = prepare_reply_for_platform_delivery(reply, principal_id=principal_id, delivery_contract=contract)

    assert str(sidecar) not in reply
    assert delivery.attachments == ()
    decision = evaluate_response_fulfillment(
        store=Store(None),
        conversation_id=principal_id,
        user_message=prompt,
        reply=reply,
        tool_results=[tool_result],
        artifact_roots=[artifact_root],
        required_attachment_extensions=(".pdf",),
    )
    assert decision.satisfied is False
    assert decision.reply == "I couldn't attach the requested file."


