def test_http_chat_delivers_browser_screenshot_tool_artifact_when_reply_references_it(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from fastapi.testclient import TestClient
    from nullion.artifacts import artifact_root_for_principal
    from nullion.runtime import bootstrap_persistent_runtime
    from nullion.web_app import create_app

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    conversation_id = "web:e2e-screenshot-primary"
    artifact_root = artifact_root_for_principal(conversation_id)
    artifact_root.mkdir(parents=True, exist_ok=True)
    image_path = artifact_root / "screenshot-196ab5c17fcf.png"
    image_path.write_bytes(b"\x89PNG\r\napi-capture")

    class Orchestrator:
        def run_turn(self, **kwargs):  # noqa: ANN003
            assert kwargs["conversation_id"] == conversation_id
            return SimpleNamespace(
                suspended_for_approval=False,
                final_text=f"Uber\nRide\nChoose a ride\n$58.93\n\nMEDIA:{image_path}",
                artifacts=[],
                tool_results=[
                    ToolResult(
                        "browser-shot",
                        "browser_screenshot",
                        "completed",
                        {
                            "path": str(image_path),
                            "artifact_path": str(image_path),
                            "artifact_paths": [str(image_path)],
                            "page_url": "https://example.com/ride",
                            "page_title": "Ride",
                        },
                    )
                ],
                reached_iteration_limit=False,
            )

    runtime = bootstrap_persistent_runtime(tmp_path / "runtime-api.db")
    app = create_app(runtime, orchestrator=Orchestrator(), registry=ToolRegistry(filesystem_allowed_roots=[tmp_path]))

    with TestClient(app) as client:
        response = client.post(
            "/api/chat",
            json={"text": "send me a screenshot?", "conversation_id": conversation_id},
        )
        assert response.status_code == 200
        payload = response.json()
        artifact = payload["artifacts"][0]
        downloaded = client.get(artifact["url"])

    assert payload["type"] == "message"
    assert payload["text"] == "Uber\nRide\nChoose a ride\n$58.93"
    assert artifact["name"] == image_path.name
    assert artifact["media_type"] == "image/png"
    assert downloaded.status_code == 200
    assert downloaded.content == b"\x89PNG\r\napi-capture"


