def test_http_chat_delivers_multi_format_artifacts_and_readable_reply(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from fastapi.testclient import TestClient
    from nullion.artifacts import artifact_root_for_principal
    from nullion.runtime import bootstrap_persistent_runtime
    from nullion.web_app import create_app

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    conversation_id = "web:e2e-readable-multi-artifact"
    artifact_root = artifact_root_for_principal(conversation_id)
    artifact_root.mkdir(parents=True, exist_ok=True)
    pdf_path = artifact_root / "readable_packet.pdf"
    xlsx_path = artifact_root / "readable_packet.xlsx"
    pdf_path.write_bytes(b"%PDF-1.7\nreadable packet")
    xlsx_path.write_bytes(b"PK\x03\x04readable workbook")
    visible_reply = "\n\n".join(
        [
            "Outcome: Created the requested packet.",
            "Tools exercised: PDF and spreadsheet artifact creation.",
            "Artifacts: `readable_packet.pdf` and `readable_packet.xlsx`.",
            "Fallbacks: None.",
            "Next: Review the two attached artifacts.",
        ]
    )

    class Orchestrator:
        def run_turn(self, **kwargs):  # noqa: ANN003
            assert kwargs["conversation_id"] == conversation_id
            return SimpleNamespace(
                suspended_for_approval=False,
                final_text=visible_reply,
                artifacts=[],
                tool_results=[
                    ToolResult("pdf", "pdf_create", "completed", {"artifact_path": str(pdf_path)}),
                    ToolResult("sheet", "spreadsheet_create", "completed", {"artifact_path": str(xlsx_path)}),
                ],
                reached_iteration_limit=False,
            )

    runtime = bootstrap_persistent_runtime(tmp_path / "runtime-api-readable-multi.db")
    app = create_app(runtime, orchestrator=Orchestrator(), registry=ToolRegistry(filesystem_allowed_roots=[tmp_path]))

    with TestClient(app) as client:
        response = client.post(
            "/api/chat",
            json={
                "text": "Create readable_packet.pdf and readable_packet.xlsx.",
                "conversation_id": conversation_id,
            },
        )
        assert response.status_code == 200
        payload = response.json()
        artifacts = payload["artifacts"]
        downloaded = {item["name"]: client.get(item["url"]) for item in artifacts}

    assert payload["type"] == "message"
    assert payload["text"] == visible_reply
    assert sorted(item["name"] for item in artifacts) == ["readable_packet.pdf", "readable_packet.xlsx"]
    assert downloaded["readable_packet.pdf"].content == b"%PDF-1.7\nreadable packet"
    assert downloaded["readable_packet.xlsx"].content == b"PK\x03\x04readable workbook"


