def test_messaging_structured_multi_format_contract_triggers_tool_scope_without_word_routing() -> None:
    from nullion import chat_operator
    from nullion.turn_context_policy import build_turn_tool_evidence

    assert chat_operator._requested_attachment_extensions(
        "Generate verified artifacts: docx, pptx, xlsx, csv, pdf, self-contained html, and linked html."
    ) == ()
    multi_format_extensions = (".docx", ".pptx", ".xlsx", ".csv", ".pdf", ".html", ".html")
    single_source_extension = chat_operator._requested_attachment_extensions(
        "Search all the pdf files on my computer and send me a text file."
    )

    assert multi_format_extensions == (".docx", ".pptx", ".xlsx", ".csv", ".pdf", ".html", ".html")
    assert single_source_extension == ()
    assert chat_operator._requested_attachment_extensions(
        "Find the PDF file named stage_file_search_delivery_guard_1234.pdf in my workspace."
    ) == ()

    evidence = build_turn_tool_evidence(
        user_message="Generate verified artifacts: docx, pptx, xlsx, csv, pdf, self-contained html, and linked html.",
        conversation_result=None,
        requested_extensions=multi_format_extensions,
    )

    assert not chat_operator._messaging_turn_skip_tool_scope_decision(
        evidence=evidence,
        user_message="Generate verified artifacts: docx, pptx, xlsx, csv, pdf, self-contained html, and linked html.",
        config_action=None,
        allow_mini_agents=False,
        force_mini_agent_dispatch=False,
        turn_dispatch_decision=None,
    )


def test_chat_embedded_media_attachment_contract_uses_structured_model_output() -> None:
    from nullion import chat_operator

    class MediaContractModel:
        def create(self, **kwargs):  # noqa: ANN003
            assert kwargs["tools"][0]["name"] == "select_attachment_format"
            return {
                "content": [
                    {
                        "type": "tool_use",
                        "name": "select_attachment_format",
                        "input": {
                            "extension": ".xlsx",
                            "confidence": 0.94,
                            "embedded_media_extensions": [".xlsx"],
                        },
                    }
                ]
            }

    assert chat_operator._requested_embedded_media_extensions(
        "画像付きの表計算ファイルを添付して",
        model_client=MediaContractModel(),
        allow_model_planning=True,
    ) == (".xlsx",)


def test_messaging_fast_profile_treats_artifact_scope_as_special() -> None:
    from types import SimpleNamespace

    from nullion import chat_operator
    from nullion.turn_context_policy import TurnToolScopeDecision

    registry = SimpleNamespace(
        turn_tool_scope_decision=TurnToolScopeDecision(
            requested_artifact_extensions=(".docx", ".pptx", ".xlsx"),
            required_embedded_media_extensions=(".docx", ".pptx"),
            valid=True,
        )
    )

    assert chat_operator._turn_tool_scope_requires_special_tools(registry)


def test_scoped_turn_registry_keeps_connector_turn_on_exact_requested_tool() -> None:
    from nullion.turn_context_policy import ScopedTurnToolRegistry, TurnToolEvidence, TurnToolScopeDecision

    registry = ToolRegistry()
    for name in ("connector_request", "email_search", "email_read", "calendar_list"):
        registry.register(
            ToolSpec(
                name=name,
                description=name,
                risk_level=ToolRiskLevel.LOW,
                side_effect_class=ToolSideEffectClass.READ,
                requires_approval=False,
                timeout_seconds=5,
                capability_tags=("connector",),
            ),
            lambda invocation: ToolResult(invocation.invocation_id, invocation.tool_name, "completed", {}),
        )

    scoped = ScopedTurnToolRegistry(
        registry,
        evidence=TurnToolEvidence(),
        tool_scope_decision=TurnToolScopeDecision(
            skill_pack_action="connector",
            connector_source_user_requested=True,
            requested_tool_names=("calendar_list",),
            valid=True,
        ),
    )

    visible = {tool["name"] for tool in scoped.list_tool_definitions()}

    assert visible == {"request_tool_scope", "calendar_list"}


def test_request_tool_scope_can_open_exact_connector_tool_without_family_bloat(monkeypatch) -> None:
    from nullion import turn_context_policy
    from nullion.turn_context_policy import scoped_turn_tool_registry, build_turn_tool_evidence

    monkeypatch.setattr(
        turn_context_policy,
        "_active_connector_provider_context",
        lambda: [
            {
                "provider_id": "skill_pack_connector_example_gateway_skill",
                "structured_tools": ["connector_request", "calendar_list"],
                "active_app_ids": ["google-calendar"],
            }
        ],
    )

    registry = ToolRegistry()
    for name in ("connector_request", "email_search", "email_read", "calendar_list"):
        registry.register(
            ToolSpec(
                name=name,
                description=name,
                risk_level=ToolRiskLevel.LOW,
                side_effect_class=ToolSideEffectClass.READ,
                requires_approval=False,
                timeout_seconds=5,
                capability_tags=("connector",),
            ),
            lambda invocation: ToolResult(invocation.invocation_id, invocation.tool_name, "completed", {}),
        )
    scoped = scoped_turn_tool_registry(
        registry,
        evidence=build_turn_tool_evidence(
            user_message="Structured numbered-option selection:\nSelected option 2:\nCalendar records",
            conversation_result=None,
            numbered_option_selected=True,
        ),
        model_client=None,
        user_message="anything",
    )

    result, widened = scoped.apply_scope_request(
        ToolInvocation(
            invocation_id="scope-1",
            tool_name="request_tool_scope",
            principal_id="telegram_chat",
            arguments={
                "capabilities": ["connector"],
                "source_user_requested": True,
                "source_evidence": "Calendar records",
                "connector_app_ids": ["google-calendar"],
                "tool_names": ["calendar_list"],
            },
        )
    )

    assert result.output["available_tools"] == ["calendar_list"]
    assert {tool["name"] for tool in widened.list_tool_definitions()} == {"request_tool_scope", "calendar_list"}


def test_request_tool_scope_web_search_exposes_continuation_ladder() -> None:
    from nullion.turn_context_policy import scoped_turn_tool_registry, build_turn_tool_evidence

    registry = ToolRegistry()
    for name in (
        "web_search",
        "web_fetch",
        "browser_navigate",
        "browser_extract_text",
        "browser_extract_items",
        "browser_run_js",
    ):
        registry.register(
            ToolSpec(
                name=name,
                description=name,
                risk_level=ToolRiskLevel.LOW,
                side_effect_class=ToolSideEffectClass.READ,
                requires_approval=False,
                timeout_seconds=5,
                capability_tags=("web",),
                continuation_tools=(
                    ("web_fetch", "browser_navigate", "browser_extract_text", "browser_extract_items")
                    if name == "web_search"
                    else ()
                ),
            ),
            lambda invocation: ToolResult(invocation.invocation_id, invocation.tool_name, "completed", {}),
        )
    scoped = scoped_turn_tool_registry(
        registry,
        evidence=build_turn_tool_evidence(user_message="live lookup", conversation_result=None),
        model_client=None,
        user_message="live lookup",
    )

    result, widened = scoped.apply_scope_request(
        ToolInvocation(
            invocation_id="scope-web",
            tool_name="request_tool_scope",
            principal_id="telegram_chat",
            arguments={"capabilities": ["web"], "tool_names": ["web_search"]},
        )
    )

    assert {
        "web_search",
        "web_fetch",
        "browser_navigate",
        "browser_extract_text",
        "browser_extract_items",
    }.issubset(set(result.output["available_tools"]))
    assert {
        "web_search",
        "web_fetch",
        "browser_navigate",
        "browser_extract_text",
        "browser_extract_items",
    }.issubset({tool["name"] for tool in widened.list_tool_definitions()})


