def test_compact_email_read_marks_http_links_for_web_followup() -> None:
    from nullion import tools

    body = '<html><body><a href="https://example.com/contact">Office contact</a></body></html>'
    encoded = base64.urlsafe_b64encode(body.encode("utf-8")).decode("ascii").rstrip("=")
    compact = tools._compact_gmail_message(
        {
            "id": "msg-1",
            "threadId": "thread-1",
            "payload": {
                "mimeType": "text/html",
                "body": {"data": encoded},
            },
        },
        include_body=True,
    )

    assert compact["links"] == [{"url": "https://example.com/contact", "text": "Office contact"}]
    assert compact["next_tools_for_links"] == ["browser_navigate", "browser_extract_text", "web_fetch"]


def test_connector_scope_enforces_selected_app_id_on_typed_tools() -> None:
    from nullion.turn_context_policy import ScopedTurnToolRegistry, TurnToolEvidence, TurnToolScopeDecision

    registry = ToolRegistry()
    for name in ("email_search", "calendar_list", "connector_request"):
        registry.register(
            ToolSpec(
                name=name,
                description=name,
                risk_level=ToolRiskLevel.LOW,
                side_effect_class=ToolSideEffectClass.READ,
                requires_approval=False,
                timeout_seconds=5,
                capability_tags=("connector",),
            ),
            lambda invocation: ToolResult(invocation.invocation_id, invocation.tool_name, "completed", {"tool": invocation.tool_name}),
        )

    scoped = ScopedTurnToolRegistry(
        registry,
        evidence=TurnToolEvidence(),
        tool_scope_decision=TurnToolScopeDecision(
            skill_pack_action="connector",
            connector_app_ids=("google-calendar",),
            connector_source_user_requested=True,
            requested_tool_names=("email_search", "calendar_list", "connector_request"),
            valid=True,
        ),
    )

    denied_email = scoped.invoke(ToolInvocation("inv-email", "email_search", "telegram_chat", {"query": "inbox"}))
    allowed_calendar = scoped.invoke(
        ToolInvocation(
            "inv-calendar",
            "calendar_list",
            "telegram_chat",
            {"start": "2026-05-30T00:00:00Z", "end": "2026-05-31T00:00:00Z"},
        )
    )
    denied_unknown_connector = scoped.invoke(
        ToolInvocation(
            "inv-connector",
            "connector_request",
            "telegram_chat",
            {"provider_id": "skill_pack_connector_maton_ai_api_gateway_skill", "url": "https://api.maton.ai/notion/v1/pages"},
        )
    )

    assert denied_email.status == "denied"
    assert denied_email.output["reason"] == "connector_app_not_in_turn_scope"
    assert allowed_calendar.status == "completed"
    assert denied_unknown_connector.status == "denied"
    assert denied_unknown_connector.output["connector_app_id"] == "notion"


