def test_context_linked_model_scope_can_declare_screenshot_artifact_without_text_triggers() -> None:
    from nullion.turn_context_policy import (
        ScopedTurnToolRegistry,
        TurnToolEvidence,
        build_turn_tool_scope_decision,
    )

    registry = ToolRegistry()
    for name, tags in (
        ("browser_open", ("web",)),
        ("browser_navigate", ("web",)),
        ("browser_extract_text", ("web",)),
        ("browser_assert_page_state", ("web",)),
        ("browser_screenshot", ("web",)),
        ("web_fetch", ("web",)),
        ("file_download", ("web",)),
        ("terminal_exec", ("local_shell",)),
    ):
        registry.register(
            ToolSpec(
                name=name,
                description=name,
                risk_level=ToolRiskLevel.LOW,
                side_effect_class=ToolSideEffectClass.READ,
                requires_approval=False,
                timeout_seconds=5,
                capability_tags=tags,
            ),
            lambda invocation: ToolResult(invocation.invocation_id, invocation.tool_name, "completed", {}),
        )

    class Client:
        def create(self, **kwargs):
            prompt = json.loads(kwargs["messages"][0]["content"][0]["text"])
            assert prompt["prior_tool_scopes"] == ["web"]
            return {
                "content": [
                    {
                        "type": "text",
                        "text": json.dumps(
                            {
                                "web_action": "browser_interaction",
                                "scheduler_action": "none",
                                "scheduler_selection_policy": "none",
                                "skill_pack_action": "none",
                                "requested_tool_names": ["browser_screenshot"],
                                "required_tool_names": [],
                                "requested_artifact_extensions": [".png"],
                                "required_embedded_media_extensions": [],
                                "confidence": 0.99,
                            }
                        ),
                    }
                ]
            }

    evidence = TurnToolEvidence(context_linked=True, prior_tool_scopes=("web",))

    decision = build_turn_tool_scope_decision(
        model_client=Client(),
        user_message="この画面を送って",
        evidence=evidence,
        registry=registry,
        force_model_decision=True,
    )
    scoped = ScopedTurnToolRegistry(registry, evidence=evidence, tool_scope_decision=decision)
    visible = {tool["name"] for tool in scoped.list_tool_definitions()}

    assert decision.valid is True
    assert decision.requested_tool_names == ("browser_screenshot",)
    assert decision.requested_artifact_extensions == (".png",)
    assert "browser_screenshot" in visible
    assert "terminal_exec" in visible


