def test_deep_agent_rejects_plain_workbook_after_embedded_media_failure(tmp_path, monkeypatch) -> None:
    from nullion.deep_agent_runner import (
        _artifact_delivery_failure_for_task,
        _deliverable_artifact_paths_for_task,
    )
    from nullion.workspace_storage import workspace_storage_roots_for_principal

    monkeypatch.setenv("NULLION_WORKSPACE_STORAGE_ROOT", str(tmp_path))
    roots = workspace_storage_roots_for_principal("telegram:123")
    workbook = roots.artifacts / "products.xlsx"
    workbook.write_bytes(b"PK\x03\x04plain workbook without embedded media")
    task = TaskRecord(
        task_id="t-sheet",
        group_id="g-sheet",
        conversation_id="telegram:123",
        principal_id="telegram:123",
        title="Create workbook",
        description="Create the requested product workbook.",
        status=TaskStatus.QUEUED,
        priority=TaskPriority.NORMAL,
        allowed_tools=["spreadsheet_create", "browser_image_collect"],
        dependencies=[],
        metadata={"requires_artifact_delivery": True, "required_artifact_kind": "xlsx"},
    )
    config = MiniAgentConfig(agent_id="a-sheet", task=task)
    deliverable = _deliverable_artifact_paths_for_task(config, [str(workbook)])
    failed_media = ToolResult(
        "sheet-remote-images",
        "spreadsheet_create",
        "failed",
        {
            "path": str(workbook),
            "reason": "remote_image_paths_not_supported",
            "remote_image_urls": ["https://example.test/image.jpg"],
            "invocation_arguments": {
                "rows": [{"Title": "Item", "image_path": "https://example.test/image.jpg"}],
                "output_path": str(workbook),
            },
        },
        "spreadsheet_create image_paths and screenshot_paths must be local artifact file paths.",
    )
    plain_replacement = ToolResult(
        "sheet-plain",
        "spreadsheet_create",
        "completed",
        {"artifact_path": str(workbook), "embedded_images": [], "embedded_screenshots": []},
    )

    assert deliverable == [str(workbook)]
    failure = _artifact_delivery_failure_for_task(
        config,
        [str(workbook)],
        deliverable,
        tool_results=[failed_media, plain_replacement],
    )

    assert failure is not None
    assert "embedded image/screenshot media" in failure


