def test_response_fulfillment_replaces_stale_media_setup_failure_after_package_success(tmp_path) -> None:
    workbook_artifact = tmp_path / "comparison.xlsx"
    csv_artifact = tmp_path / "comparison.csv"
    pdf_artifact = tmp_path / "summary.pdf"
    screenshot_artifact = tmp_path / "screenshot.png"
    workbook_artifact.write_bytes(b"PK\x03\x04fake workbook")
    csv_artifact.write_text("name,score\nA,1\n", encoding="utf-8")
    pdf_artifact.write_bytes(b"%PDF-1.4 fake")
    screenshot_artifact.write_bytes(b"\x89PNG\r\n\x1a\nfake")
    failed_setup_reply = (
        "I couldn't create the requested file with `spreadsheet create`: "
        "This turn requires the spreadsheet artifact to contain embedded image/screenshot media. "
        "Do not create or deliver a replacement artifact without embedded media; fetch or save local raster "
        "artifact files first, then retry with row- or artifact-aligned image/screenshot path inputs.."
    )
    failed_workbook = ToolResult(
        "failed",
        "spreadsheet_create",
        "failed",
        {
            "reason": "artifact_media_required_by_turn_contract",
            "artifact_extensions": [".xlsx", ".csv", ".pdf"],
            "embedded_media_artifact_extensions": [".xlsx"],
        },
        (
            "This turn requires the spreadsheet artifact to contain embedded image/screenshot media. "
            "Do not create or deliver a replacement artifact without embedded media; fetch or save local raster "
            "artifact files first, then retry with row- or artifact-aligned image/screenshot path inputs.."
        ),
    )
    embedded_workbook = ToolResult(
        "embedded",
        "spreadsheet_create",
        "completed",
        {
            "path": str(workbook_artifact),
            "artifact_path": str(workbook_artifact),
            "embedded_images": [],
            "embedded_screenshots": [str(screenshot_artifact)],
        },
    )
    csv_file = ToolResult("csv", "spreadsheet_create", "completed", {"path": str(csv_artifact), "format": "csv"})
    failed_pdf = ToolResult(
        "failed-pdf",
        "pdf_create",
        "failed",
        {
            "reason": "artifact_media_inputs_failed",
            "image_paths": [str(screenshot_artifact)],
            "screenshot_paths": [],
            "source_image_paths": [],
            "source_screenshot_paths": [],
        },
        "Browser screenshot artifacts must be supplied through screenshot_paths.",
    )
    pdf_file = ToolResult(
        "pdf",
        "pdf_create",
        "completed",
        {
            "path": str(pdf_artifact),
            "artifact_path": str(pdf_artifact),
            "source_screenshot_paths": [str(screenshot_artifact)],
        },
    )

    decision = evaluate_response_fulfillment(
        store=Store(None),
        conversation_id="c1",
        user_message="Create a workbook, CSV, and PDF with media in the workbook",
        reply=failed_setup_reply,
        tool_results=[failed_workbook, embedded_workbook, csv_file, failed_pdf, pdf_file],
        artifact_roots=[tmp_path],
        required_attachment_extensions=(".xlsx", ".csv", ".pdf"),
        required_embedded_media_extensions=(".xlsx",),
    )

    assert decision.satisfied is True
    assert "spreadsheet create" not in decision.reply
    assert "comparison.xlsx" in decision.reply
    assert "comparison.csv" in decision.reply
    assert "summary.pdf" in decision.reply


