def test_platform_delivery_uses_nullion_home_for_workspace_artifacts(monkeypatch, tmp_path) -> None:
    from nullion.artifacts import artifact_root_for_principal
    from nullion.messaging_adapters import delivery_contract_for_turn, prepare_reply_for_platform_delivery

    nullion_home = tmp_path / "stage-home"
    monkeypatch.delenv("NULLION_DATA_DIR", raising=False)
    monkeypatch.setenv("NULLION_HOME", str(nullion_home))
    artifact_root = artifact_root_for_principal("telegram_chat")
    artifact_root.mkdir(parents=True, exist_ok=True)
    workbook_artifact = artifact_root / "etsy_witches_comparison.xlsx"
    workbook_artifact.write_bytes(b"PK\x03\x04fake workbook with embedded listing images")
    reply = f"Created the spreadsheet.\nMEDIA:{workbook_artifact}"

    delivery_contract = delivery_contract_for_turn(
        None,
        reply=reply,
        artifact_paths=[str(workbook_artifact)],
        requires_attachment_delivery=True,
        required_attachment_extensions=(".xlsx",),
    )
    delivery = prepare_reply_for_platform_delivery(
        reply,
        principal_id="telegram_chat",
        delivery_contract=delivery_contract,
    )

    assert delivery.text == "Created the spreadsheet."
    assert delivery.attachments == (workbook_artifact,)
    assert delivery.unavailable_attachment_count == 0


