def test_browser_image_html_candidate_parser_handles_real_world_asset_patterns() -> None:
    from nullion.tools import _browser_image_candidates_from_html

    html = """
    <html>
      <head>
        <meta property="og:image" content="/social.jpg">
        <script type="application/ld+json">
          {"@type":"ImageObject","contentUrl":"/jsonld.jpg"}
        </script>
      </head>
      <body>
        <picture><source srcset="/large.webp 2x, /small.webp 1x"></picture>
        <img data-image-src="/lazy.jpg" alt="Lazy asset">
        <section style="background-image: url('/hero.png')"></section>
      </body>
    </html>
    """

    candidates = _browser_image_candidates_from_html(html, page_url="https://example.test/gallery/page")
    urls = {candidate["source_url"] for candidate in candidates}

    assert "https://example.test/social.jpg" in urls
    assert "https://example.test/jsonld.jpg" in urls
    assert "https://example.test/large.webp" in urls
    assert "https://example.test/lazy.jpg" in urls
    assert "https://example.test/hero.png" in urls


