def test_chat_repair_reply_drops_stale_media_failure_after_embedded_pdf_success(monkeypatch, tmp_path) -> None:
    from nullion import chat_operator

    artifact_root = tmp_path / "artifacts"
    artifact_root.mkdir()
    image_artifact = artifact_root / "source-image.png"
    pdf_artifact = artifact_root / "recreated-with-images.pdf"
    image_artifact.write_bytes(b"\x89PNG\r\n\x1a\n")
    pdf_artifact.write_bytes(b"%PDF-1.4\n%embedded images\n")
    failed_plain_pdf = ToolResult(
        "plain",
        "pdf_create",
        "failed",
        {
            "reason": "artifact_media_required_by_turn_contract",
            "embedded_media_artifact_extensions": [".pdf"],
            "artifact_extensions": [".pdf"],
        },
        "This turn requires the PDF artifact to contain embedded image/screenshot media.",
    )
    embedded_pdf = ToolResult(
        "embedded",
        "pdf_create",
        "completed",
        {
            "artifact_path": str(pdf_artifact),
            "source_image_paths": [str(image_artifact)],
            "source_screenshot_paths": [],
        },
    )

    repair_reply, deferred = chat_operator._repair_final_text_for_completed_media_artifact(
        repair_reply="I couldn't create the requested file with `pdf create`.",
        repair_tool_results=[failed_plain_pdf, embedded_pdf],
        combined_tool_results=[failed_plain_pdf, embedded_pdf],
    )

    monkeypatch.setattr(chat_operator, "artifact_root_for_principal", lambda principal_id: artifact_root)
    monkeypatch.setattr(chat_operator, "artifact_root_for_runtime", lambda runtime: artifact_root)
    rendered = chat_operator._append_chat_artifacts_to_reply(
        SimpleNamespace(),
        reply=repair_reply,
        artifact_paths=[str(pdf_artifact)],
        prompt="Recreate it",
        tool_results=[failed_plain_pdf, embedded_pdf],
        required_attachment_extensions=(".pdf",),
    )

    assert deferred is True
    assert "couldn't" not in rendered
    assert "Done" in rendered
    assert f"MEDIA:{pdf_artifact}" in rendered


def test_media_artifact_plain_replacement_guard_covers_non_spreadsheet_tools(tmp_path) -> None:
    source_pdf = tmp_path / "source.pdf"
    source_pdf.write_bytes(b"%PDF-1.4\n")
    cases = [
        ("document_create", ".docx", {"paragraphs": ["body"]}, {"paragraphs": ["body"], "image_paths": ["product.jpg"]}),
        (
            "presentation_create",
            ".pptx",
            {"slides": [{"title": "body"}]},
            {"slides": [{"title": "body", "image_paths": ["product.jpg"]}]},
        ),
        ("pdf_create", ".pdf", {"text_pages": ["body"]}, {"image_paths": ["product.jpg"]}),
        (
            "pdf_edit",
            ".pdf",
            {"input_path": str(source_pdf)},
            {"input_path": str(source_pdf), "append_image_paths": ["product.jpg"]},
        ),
    ]

    for tool_name, extension, plain_args, media_args in cases:
        failed_media = ToolResult(
            "failed",
            tool_name,
            "failed",
            {"reason": "artifact_media_inputs_failed", "skipped_images": ["missing.jpg"]},
            "media input failed",
        )
        plain_invocation = ToolInvocation("plain", tool_name, "telegram:1", plain_args)
        media_invocation = ToolInvocation("media", tool_name, "telegram:1", media_args)

        guarded = artifact_media_plain_replacement_guard_result(plain_invocation, [failed_media])

        if tool_name == "pdf_edit":
            # Edits preserve input objects; the saved-file contract validates media.
            assert guarded is None
        else:
            assert guarded is not None
            assert guarded.output["reason"] == "artifact_media_required_by_prior_failure"
            assert guarded.output["artifact_extensions"] == [extension]
        assert artifact_media_plain_replacement_guard_result(media_invocation, [failed_media]) is None


