def test_sanitizer_humanizes_file_search_payload_without_paths() -> None:
    result = ToolResult(
        "search-1",
        "file_search",
        "completed",
        {
            "matches": [
                "/Users/example/.nullion/workspaces/workspace_admin/artifacts/provincetown_airbnb_monitor_2026-04-30_images-fixed.html"
            ]
        },
    )
    raw_reply = (
        '{"matches": ["/Users/example/.nullion/workspaces/workspace_admin/artifacts/'
        'provincetown_airbnb_monitor_2026-04-30_images-fixed.html"]}'
    )

    sanitized = sanitize_user_visible_reply(
        user_message="Images are missing",
        reply=raw_reply,
        tool_results=[result],
        source="agent",
    )

    assert sanitized == (
        "I found 1 matching file: `provincetown_airbnb_monitor_2026-04-30_images-fixed.html`. "
        "I have not read the file contents yet, so this is evidence, not the final answer."
    )
    assert "/Users/example" not in sanitized
    assert "blocked a raw structured payload" not in sanitized

    preview_payload = json.dumps(
        {
            "match_details": [
                {
                    "match_type": "filename",
                    "path": "/Users/example/.nullion/workspaces/workspace_admin/artifacts/weather_today.pdf",
                }
            ],
            "matches": [],
            "truncated": True,
        },
        sort_keys=True,
    )
    preview_result = ToolResult(
        "search-2",
        "file_search",
        "completed",
        {"truncated": True, "original_chars": len(preview_payload), "preview": preview_payload},
    )

    preview_sanitized = sanitize_user_visible_reply(
        user_message="file-backed question",
        reply=preview_payload,
        tool_results=[preview_result],
        source="agent",
    )

    assert "weather_today.pdf" in preview_sanitized
    assert "/Users/example" not in preview_sanitized
    assert "evidence, not the final answer" in preview_sanitized


