def test_sanitizer_repairs_collapsed_numbered_final_reply() -> None:
    sanitized = sanitize_user_visible_reply(
        user_message="/planner Build a QA plan",
        reply=(
            "Here is the plan: 1. Rendered image recovery: define cases and expected behavior. "
            "2. Connector scoping: validate only needed tools are used. "
            "3. Artifact delivery: verify files are attached and readable."
        ),
        tool_results=[],
        source="agent",
    )

    assert sanitized == (
        "Here is the plan:\n"
        "1. Rendered image recovery: define cases and expected behavior.\n"
        "2. Connector scoping: validate only needed tools are used.\n"
        "3. Artifact delivery: verify files are attached and readable."
    )

    parenthesized = sanitize_user_visible_reply(
        user_message="Make a QA plan",
        reply=(
            "Stage QA plan: (1) Scope: verify final replies are readable. "
            "(2) Plan: run Telegram and web checks. "
            "(3) Acceptance: no collapsed list output reaches users."
        ),
        tool_results=[],
        source="agent",
    )
    assert parenthesized == (
        "Stage QA plan:\n"
        "(1) Scope: verify final replies are readable.\n"
        "(2) Plan: run Telegram and web checks.\n"
        "(3) Acceptance: no collapsed list output reaches users."
    )

    orphaned = sanitize_user_visible_reply(
        user_message="Make a QA plan",
        reply=(
            "(2) Plan: run the checks.\n"
            "(3) Acceptance: no broken numbering reaches users."
        ),
        tool_results=[],
        source="agent",
    )
    assert orphaned == (
        "(1) Plan: run the checks.\n"
        "(2) Acceptance: no broken numbering reaches users."
    )


