def test_existing_file_scope_preserves_active_typed_artifact_contract() -> None:
    from nullion.chat_operator import _merge_active_artifact_contract_into_scope_decision
    from nullion.turn_context_policy import TurnToolScopeDecision

    existing_file_decision = TurnToolScopeDecision(
        requested_tool_names=("file_search", "file_read", "file_write"),
        requested_artifact_extensions=(".docx", ".xlsx", ".csv", ".pdf", ".html", ".json", ".txt"),
        confidence=1.0,
        valid=True,
    )
    active_decision = TurnToolScopeDecision(
        requested_tool_names=("document_create", "spreadsheet_create", "pdf_create", "file_write"),
        requested_artifact_extensions=(".docx", ".xlsx", ".csv", ".pdf", ".html"),
        excluded_artifact_extensions=(".json", ".txt"),
        required_embedded_media_extensions=(".xlsx",),
        confidence=1.0,
        valid=True,
    )

    merged = _merge_active_artifact_contract_into_scope_decision(existing_file_decision, active_decision)

    assert merged.requested_artifact_extensions == (".docx", ".xlsx", ".csv", ".pdf", ".html")
    assert merged.excluded_artifact_extensions == (".json", ".txt")
    assert merged.required_embedded_media_extensions == (".xlsx",)
    assert {"document_create", "spreadsheet_create", "pdf_create", "file_search", "file_read"} <= set(
        merged.requested_tool_names
    )


def test_embedded_media_scope_preserves_typed_excluded_formats() -> None:
    from nullion.chat_operator import _scope_decision_with_planned_embedded_media
    from nullion.turn_context_policy import TurnToolScopeDecision

    existing = TurnToolScopeDecision(
        requested_artifact_extensions=(".docx", ".xlsx", ".csv", ".pdf", ".html"),
        excluded_artifact_extensions=(".json", ".txt"),
        confidence=0.9,
        valid=True,
    )

    planned = _scope_decision_with_planned_embedded_media(
        existing,
        requested_attachment_extensions=(".docx", ".xlsx", ".csv", ".pdf", ".html", ".json", ".txt"),
        planned_embedded_media_extensions=(".xlsx",),
    )

    assert planned.requested_artifact_extensions == (".docx", ".xlsx", ".csv", ".pdf", ".html")
    assert planned.excluded_artifact_extensions == (".json", ".txt")
    assert planned.required_embedded_media_extensions == (".xlsx",)


