def test_scoped_artifact_extensions_prefer_final_package_over_support_sidecars(tmp_path: Path) -> None:
    docx = tmp_path / "deliverable.docx"
    xlsx = tmp_path / "deliverable.xlsx"
    csv = tmp_path / "deliverable.csv"
    pdf = tmp_path / "deliverable.pdf"
    html = tmp_path / "deliverable.html"
    side_json = tmp_path / "helper_status.json"
    side_txt = tmp_path / "helper_status.txt"
    side_png = tmp_path / "helper_preview.png"
    for path in (docx, xlsx):
        path.write_bytes(b"PK\x03\x04")
    csv.write_text("name,value\nqa,1\n", encoding="utf-8")
    pdf.write_bytes(b"%PDF-1.4\n")
    html.write_text("<html><img src='data:image/png;base64,abc'></html>", encoding="utf-8")
    side_json.write_text("{}", encoding="utf-8")
    side_txt.write_text("internal status", encoding="utf-8")
    side_png.write_bytes(b"\x89PNG\r\n\x1a\n")
    tool_results = [
        ToolResult("png-scope", "request_tool_scope", "completed", {"artifact_extensions": [".png"]}),
        ToolResult(
            "final-scope",
            "request_tool_scope",
            "completed",
            {
                "artifact_extensions": [".docx", ".xlsx", ".csv", ".pdf", ".html"],
                "embedded_media_artifact_extensions": [".xlsx"],
            },
        ),
        ToolResult("docx", "document_create", "completed", {"artifact_path": str(docx)}),
        ToolResult("xlsx", "spreadsheet_create", "completed", {"artifact_path": str(xlsx), "embedded_images": [str(side_png)]}),
        ToolResult("csv", "file_write", "completed", {"path": str(csv), "artifact_path": str(csv)}),
        ToolResult("pdf", "pdf_create", "completed", {"artifact_path": str(pdf)}),
        ToolResult("html", "file_write", "completed", {"path": str(html), "artifact_path": str(html)}),
        ToolResult(
            "support-scope",
            "request_tool_scope",
            "completed",
            {"artifact_extensions": [".json", ".txt", ".png"]},
        ),
        ToolResult("json", "file_write", "completed", {"path": str(side_json), "artifact_path": str(side_json)}),
        ToolResult("txt", "file_write", "completed", {"path": str(side_txt), "artifact_path": str(side_txt)}),
        ToolResult("png", "file_write", "completed", {"path": str(side_png), "artifact_path": str(side_png)}),
    ]

    assert scoped_artifact_extensions_from_tool_results(tool_results) == (
        ".docx",
        ".xlsx",
        ".csv",
        ".pdf",
        ".html",
    )
    assert artifact_paths_from_tool_results(tool_results) == [
        str(docx),
        str(xlsx),
        str(csv),
        str(pdf),
        str(html),
    ]


