def test_completed_requested_artifact_selector_waits_for_scoped_email_send(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from nullion.artifacts import artifact_root_for_principal
    from nullion.chat_operator import _completed_requested_artifact_paths_for_turn_result
    from nullion.runtime import bootstrap_persistent_runtime

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    monkeypatch.setenv("NULLION_HOME", str(tmp_path / "home"))
    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    principal_id = "web:email-package-selector"
    artifact_root = artifact_root_for_principal(principal_id)
    artifact_root.mkdir(parents=True, exist_ok=True)
    csv_path = artifact_root / "stage_qa_test_data.csv"
    csv_path.write_text("name,value\nqa,1\n", encoding="utf-8")

    class ResultWithoutEmail:
        final_text = "Done"
        artifacts = [str(csv_path)]
        tool_results = [
            ToolResult(
                "scope",
                "request_tool_scope",
                "completed",
                {
                    "artifact_extensions": [".csv"],
                    "available_tools": ["file_write", "email_send"],
                },
            ),
            ToolResult(
                "csv",
                "file_write",
                "completed",
                {
                    "artifact_path": str(csv_path),
                    "artifact_paths": [str(csv_path)],
                },
            ),
        ]

