def test_direct_existing_named_artifact_rejects_new_content_from_structured_classifier(tmp_path: Path) -> None:
    from nullion.chat_operator import _direct_existing_named_workspace_artifact_action

    stale_artifact = tmp_path / "community_night_market_poster_STAGE_FORMAT_QA.pdf"
    stale_artifact.write_bytes(b"%PDF-1.4\n")

    class Model:
        called = False

        def create(self, **_: object) -> object:
            self.called = True
            return SimpleNamespace(
                output_text='{"action":"use_tools","requires_new_or_modified_content":true}'
            )

    model = Model()

    assert (
        _direct_existing_named_workspace_artifact_action(
            existing_named_artifact_paths=(str(stale_artifact),),
            effective_prompt=(
                "Create community_night_market_poster_STAGE_FORMAT_QA.pdf "
                "with fresh content for this run."
            ),
            attachment_context_present=False,
            saved_history_available=False,
            conversation_result=None,
            numbered_option_context=None,
            reply_context_prompt=None,
            planner_requested=False,
            model_client=model,
            structured_context_available=False,
        )
        == "use_tools"
    )
    assert model.called is True


