def test_last_mile_spreadsheet_artifact_uses_structured_browser_image_rows(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from openpyxl import load_workbook
    from PIL import Image

    from nullion.artifacts import artifact_root_for_principal
    from nullion.chat_operator import _materialize_last_mile_spreadsheet_artifacts

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    monkeypatch.setenv("NULLION_HOME", str(tmp_path / "home"))
    principal_id = "telegram:test-chat"
    artifact_root = artifact_root_for_principal(principal_id)
    artifact_root.mkdir(parents=True, exist_ok=True)
    first_image = artifact_root / "first.jpg"
    second_image = artifact_root / "second.jpg"
    Image.new("RGB", (96, 80), color=(200, 20, 20)).save(first_image)
    Image.new("RGB", (96, 80), color=(20, 80, 200)).save(second_image)

    first_url = "https://example.test/images/first.jpg"
    second_url = "https://example.test/images/second.jpg"
    tool_results = [
        ToolResult(
            "items",
            "browser_extract_items",
            "completed",
            {
                "items": [
                    {
                        "title": "SKU-100_RED_STONE.jpg",
                        "url": "https://example.test/item/100",
                        "image_url": first_url,
                    },
                    {
                        "title": "SKU-200_BLUE_STONE.jpg",
                        "url": "https://example.test/item/200",
                        "image_url": second_url,
                    },
                ]
            },
        ),
        ToolResult(
            "images",
            "browser_image_collect",
            "completed",
            {
                "images": [
                    {"local_path": str(first_image), "source_url": first_url},
                    {"local_path": str(second_image), "source_url": second_url},
                ],
                "image_paths": [str(first_image), str(second_image)],
            },
        ),
    ]

    results, paths = _materialize_last_mile_spreadsheet_artifacts(
        principal_id=principal_id,
        prompt="Create a workbook from browser image rows.",
        reply="Done.",
        missing_extensions=(".xlsx",),
        collected_media_paths=(str(first_image), str(second_image)),
        tool_results=tool_results,
    )

    assert len(results) == 1
    assert len(paths) == 1
    assert results[0].output["rows"] == 2
    assert results[0].output["embedded_images"] == [str(first_image), str(second_image)]
    with zipfile.ZipFile(paths[0]) as workbook:
        assert len([name for name in workbook.namelist() if name.startswith("xl/media/")]) == 2
    workbook = load_workbook(paths[0])
    sheet = workbook.active
    assert sheet.title == "Manifest"
    headers = [sheet.cell(1, column).value for column in range(1, sheet.max_column + 1)]
    assert headers == ["Original filename", "Uppercase extension", "Reversed stem", "Source URL", "Image source URL", "Image"]
    assert sheet["A2"].value == "SKU-100_RED_STONE.jpg"
    assert sheet["B2"].value == "JPG"
    assert sheet["C2"].value == "ENOTS_DER_001-UKS"
    assert all(not str(header).startswith("Part ") for header in headers)
    assert len(getattr(sheet, "_images", [])) == 2


