def test_last_mile_spreadsheet_detects_rich_existing_workbook_without_metadata(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    from openpyxl import Workbook
    from openpyxl.chart import BarChart, Reference
    from openpyxl.formatting.rule import DataBarRule
    from nullion.artifacts import artifact_root_for_principal
    from nullion.chat_operator import _materialize_last_mile_spreadsheet_artifacts
    from PIL import Image

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    monkeypatch.setenv("NULLION_HOME", str(tmp_path / "home"))
    principal_id = "telegram:test-chat"
    artifact_root = artifact_root_for_principal(principal_id)
    artifact_root.mkdir(parents=True, exist_ok=True)
    workbook_path = artifact_root / "rich-without-metadata.xlsx"
    workbook = Workbook()
    sheet = workbook.active
    sheet.append(["Location", "Setup Cost", "Revenue", "Gross Profit"])
    sheet.append(["Riverside", 1000, 2500, "=C2-B2"])
    sheet.append(["Garden", 1200, 2800, "=C3-B3"])
    chart = BarChart()
    chart.add_data(Reference(sheet, min_col=4, min_row=1, max_row=3), titles_from_data=True)
    chart.set_categories(Reference(sheet, min_col=1, min_row=2, max_row=3))
    sheet.add_chart(chart, "F2")
    sheet.conditional_formatting.add("D2:D3", DataBarRule(start_type="min", end_type="max", color="638EC6"))
    workbook.save(workbook_path)
    visual = artifact_root / "source.png"
    Image.new("RGB", (900, 600), (40, 120, 200)).save(visual)

    results, paths = _materialize_last_mile_spreadsheet_artifacts(
        principal_id=principal_id,
        prompt="Create an XLSX workbook with formulas, a chart, and conditional formatting.",
        reply="Created rich-without-metadata.xlsx",
        missing_extensions=(".xlsx",),
        collected_media_paths=(str(visual),),
        tool_results=[
            ToolResult(
                "xlsx",
                "spreadsheet_create",
                "completed",
                {"artifact_path": str(workbook_path)},
            )
        ],
    )

    assert results == []
    assert paths == []


