def test_browser_answer_preservation_prefers_completed_browser_extract_over_assertion_failure_drift() -> None:
    extracted = "Fuente de noticias\n1. Titular uno\n2. Titular dos\n3. Titular tres"
    failure_message = "structured assertion failed: TOKEN-987"

    draft_reply = ("Estado interno: TOKEN-987.\n\n"
            f"{failure_message}")
    reply = sanitize_user_visible_reply(
        user_message="Dame diez noticias actuales.",
        reply=(
            "Estado interno: TOKEN-987.\n\n"
            f"{failure_message}"
        ),
        tool_results=[
            ToolResult("extract", "browser_extract_text", "completed", {"text": extracted}),
            ToolResult(
                "assert",
                "browser_assert_page_state",
                "completed",
                {
                    "verified": False,
                    "message": failure_message,
                    "missing_required": ["TOKEN-987"],
                    "result": {"missing": [{"expected": "TOKEN-987"}]},
                },
            ),
        ],
        source="agent",
    )

    assert reply == sanitize_user_visible_reply(user_message=None, reply=draft_reply, tool_results=[])


