def test_inline_html_reply_is_promoted_to_preview_artifact(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    from nullion import artifacts

    preview = tmp_path / "email-preview.html"
    monkeypatch.setattr(artifacts, "artifact_path_for_generated_workspace_file", lambda **_kwargs: preview)
    html = "<div style='background:#111;color:#fff'>" + ("<p>Hello</p>" * 80) + "</div>"

    reply, path = artifacts.materialize_inline_html_reply_artifact(
        f"Subject: Hi\n\n```html\n{html}\n```",
        principal_id="telegram:123",
    )

    assert path == str(preview)
    assert preview.read_text(encoding="utf-8").startswith("<!doctype html>")
    assert "```html" not in str(reply)
    assert "<div style" not in str(reply)
    assert f"MEDIA:{preview}" in str(reply)


def test_email_send_accepts_html_body_as_mime_alternative() -> None:
    from nullion.tools import _email_message_for_invocation

    invocation = ToolInvocation(
        "email-html",
        "email_send",
        "telegram:123",
        {
            "to": ["nathan@example.com"],
            "subject": "Styled note",
            "body": "Plain fallback",
            "html_body": "<section><h1>Styled note</h1><p>Hello</p></section>",
        },
    )

    message, attachments = _email_message_for_invocation(invocation)

    assert attachments == []
    assert message.is_multipart()
    html_parts = [part for part in message.walk() if part.get_content_type() == "text/html"]
    text_parts = [part for part in message.walk() if part.get_content_type() == "text/plain"]
    assert html_parts
    assert text_parts
    assert "<section>" in html_parts[0].get_content()
    assert "Plain fallback" in text_parts[0].get_content()


def test_email_approval_card_attaches_html_preview_for_messaging_platforms(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    from nullion.approvals import create_approval_request
    from nullion.artifacts import artifact_root_for_principal
    from nullion.messaging_adapters import prepare_reply_for_platform_delivery
    from nullion.telegram_app import _approval_card_text

    monkeypatch.setenv("NULLION_DATA_DIR", str(tmp_path / "data"))
    preview = artifact_root_for_principal("telegram:123") / "nullion-artifact-styled-email.html"
    preview.parent.mkdir(parents=True, exist_ok=True)
    preview.write_text(
        "<!doctype html><html><body><h1>Styled email</h1><p>Preview before send.</p></body></html>",
        encoding="utf-8",
    )
    approval = create_approval_request(
        requested_by="telegram:123",
        action="use_tool",
        resource="email_send",
        context={
            "tool_name": "email_send",
            "html_preview_path": str(preview),
            "tool_arguments": {
                "to": ["nathan@example.com"],
                "subject": "Styled note",
                "body": "Plain fallback",
                "html_body": "<h1>Styled email</h1>",
            },
        },
    )

    card_text = _approval_card_text(approval)
    delivery = prepare_reply_for_platform_delivery(card_text, principal_id="telegram:123")

    assert f"MEDIA:{preview}" in card_text
    assert delivery.attachments == (preview,)
    assert "Plain fallback" in (delivery.text or "")
    assert "MEDIA:" not in (delivery.text or "")


def test_sanitizer_removes_account_connector_diagnostics_from_successful_reply() -> None:
    result = ToolResult(
        "calendar",
        "calendar_list",
        "completed",
        {
            "result_count": 1,
            "results": [
                {
                    "summary": "Lunch with Nathan",
                    "start": {"dateTime": "2026-05-17T12:00:00-04:00"},
                    "end": {"dateTime": "2026-05-17T13:00:00-04:00"},
                }
            ],
        },
    )
    connector = ToolResult(
        "connector",
        "connector_request",
        "failed",
        {"url": "https://api.maton.ai/google-calendar/calendar/v3/calendars/primary/events"},
        "blocked by connector URL policy",
    )

    sanitized = sanitize_user_visible_reply(
        user_message="check my calendar",
        reply=(
            "I checked your calendar and found Lunch with Nathan.\n\n"
            "I also attempted the lower-level connector route, but it was blocked by the connector URL policy. "
            "If you want, I can also check tomorrow."
        ),
        tool_results=[result, connector],
        source="agent",
    )

    assert sanitized is not None
    assert sanitized.startswith("📅 I checked your calendar")
    assert "lower-level connector" not in sanitized
    assert "connector URL policy" not in sanitized
    assert "api.maton.ai" not in sanitized


