def test_sanitizer_does_not_infer_calendar_relevance_from_user_words() -> None:
    result = ToolResult(
        "calendar",
        "calendar_list",
        "completed",
        {
            "result_count": 4,
            "results": [
                {
                    "summary": "Wrecked",
                    "start": {"date": "2026-06-06"},
                    "end": {"date": "2026-06-07"},
                },
                {
                    "summary": "Payment due: Chase Credit Card (...1713)",
                    "start": {"date": "2026-06-07"},
                    "end": {"date": "2026-06-08"},
                },
                {
                    "summary": "Payment due: Chase Prime Visa (...1713)",
                    "start": {"date": "2026-06-07"},
                    "end": {"date": "2026-06-08"},
                },
                {
                    "summary": "Reminder: pay American Express card ending 15007",
                    "start": {"date": "2026-06-07"},
                    "end": {"date": "2026-06-08"},
                },
            ],
        },
    )

    sanitized = sanitize_user_visible_reply(
        user_message="Can u see if there's a wrecked party this weekend?",
        reply=(
            "📅 I checked your calendar. Found 4 events:\n"
            "- 2026-06-06 - 2026-06-07: Wrecked\n"
            "- 2026-06-07 - 2026-06-08: Payment due: Chase Credit Card (...1713)\n"
            "- 2026-06-07 - 2026-06-08: Payment due: Chase Prime Visa (...1713)\n"
            "- 2026-06-07 - 2026-06-08: Reminder: pay American Express card ending 15007"
        ),
        tool_results=[result],
        source="agent",
    )

    assert sanitized.startswith("📅 I checked your calendar. Found 4 events:")
    assert "Wrecked" in sanitized
    assert "Chase" in sanitized
    assert "American Express" in sanitized


