def test_no_tool_scope_retry_skips_tool_backed_browser_verification_blocker() -> None:
    from nullion import chat_operator

    registry = ToolRegistry()
    initial_result = SimpleNamespace(
        turn_id="turn-browser-blocker",
        final_text=(
            "Live-search blocker: the browser/search tools did not produce verified result records "
            "from this run, so I do not have a reliable final answer for this request yet."
        ),
        tool_results=[
            ToolResult("scope", "request_tool_scope", "completed", {"available_tools": ["browser_navigate"]}),
            ToolResult("nav", "browser_navigate", "completed", {"result": {"url": "https://example.test"}}),
            ToolResult("text", "browser_extract_text", "completed", {"text": "General page text"}),
        ],
        artifacts=[],
        suspended_for_approval=False,
    )
    calls: list[object] = []

    recovered, returned_registry, retried = chat_operator._run_chat_turn_no_tool_scope_decision_retry(
        initial_result=initial_result,
        base_history=[],
        active_tool_registry=registry,
        base_tool_registry=registry,
        runtime=None,
        model_client=object(),
        principal_id="telegram:100001",
        user_message="Find live result records.",
        evidence=SimpleNamespace(),
        run_turn=lambda history, retry_registry: calls.append((history, retry_registry)),
    )

    assert recovered is initial_result
    assert returned_registry is registry
    assert retried is False
    assert calls == []


def test_schema_followup_directly_recovers_failed_read_from_completed_source_results() -> None:
    from nullion import chat_operator
    from nullion.tools import register_email_plugin

    registry = ToolRegistry(plugin_registration_allowed=True)
    read_ids: list[str] = []

    def reader(message_id: str) -> dict[str, object]:
        read_ids.append(message_id)
        return {
            "id": message_id,
            "subject": "Lease update",
            "from": "Rose <rose@example.com>",
            "date": "Mon, 8 Jun 2026 14:26:18 -0400",
            "snippet": "Please send the signed lease.",
        }

    register_email_plugin(
        registry,
        email_searcher=lambda query, limit: [],
        email_reader=reader,
    )
    initial_result = SimpleNamespace(
        turn_id="turn-1",
        final_text="I couldn't open that email message. I need to run a fresh email search.",
        tool_results=[
            ToolResult(
                "search",
                "email_search",
                "completed",
                {
                    "provider_id": "custom_connector_provider",
                    "results": [
                        {"id": "draft-1", "labelIds": ["DRAFT"], "subject": "Draft"},
                        {"id": "msg-1", "labelIds": ["SENT"], "subject": "Lease update"},
                    ],
                },
            ),
            ToolResult(
                "read",
                "email_read",
                "failed",
                {
                    "id": "Rosemarie",
                    "reason": "invalid_message_id",
                    "required_source_tool": "email_search",
                },
                error="Invalid email message id",
            ),
        ],
        artifacts=[],
        suspended_for_approval=False,
    )
    synthesis_calls: list[list[dict[str, object]]] = []

    def synthesize(history, retry_registry):  # noqa: ANN001
        synthesis_calls.append(history)
        assert retry_registry.list_tool_definitions() == []
        assert "Recovered evidence:" in history[-1]["content"][0]["text"]
        return SimpleNamespace(
            turn_id="turn-1",
            final_text="Recommendation: send a concise follow-up asking for a signed lease ETA.",
            tool_results=[],
            artifacts=[],
            suspended_for_approval=False,
        )

    recovered, active_registry, retried = chat_operator._run_chat_turn_schema_followup_tool_retry(
        initial_result=initial_result,
        base_history=[],
        active_tool_registry=registry,
        base_tool_registry=registry,
        evidence=None,
        run_turn=synthesize,
        principal_id="telegram:100001",
        user_message="Check account records.",
    )

    assert retried is True
    assert active_registry is registry
    assert read_ids == ["msg-1"]
    assert synthesis_calls
    assert recovered.final_text == "Recommendation: send a concise follow-up asking for a signed lease ETA."
    assert [result.tool_name for result in recovered.tool_results] == ["email_search", "email_read", "email_read"]
    assert recovered.tool_results[-1].status == "completed"


