def test_compact_scope_fallback_mentions_builder_for_connector_scope(tmp_path: Path) -> None:
    from nullion import chat_operator
    from nullion.builder import builder_proposal_acceptance_benefit
    from nullion.runtime import PersistentRuntime
    from nullion.runtime_store import RuntimeStore

    scope_result = ToolResult(
        "scope",
        "request_tool_scope",
        "completed",
        {
            "scope_requested": True,
            "capabilities": ["connector"],
            "connector_app_ids": ["example-drive"],
            "available_tools": ["connector_request"],
            "message": "Tool scope updated.",
        },
    )
    runtime = PersistentRuntime(
        store=RuntimeStore(),
        checkpoint_path=tmp_path / "runtime.db",
        started_at=datetime(2026, 6, 9, tzinfo=UTC),
    )

    reply = chat_operator._compact_unstructured_clarification_fallback(
        [scope_result],
        runtime=runtime,
    )

    assert "Builder" in reply
    assert "Example Drive" in reply
    assert "opened a Builder suggestion" in reply
    assert "Which item" not in reply
    [proposal] = runtime.list_pending_builder_proposals()
    assert proposal.proposal.title == "Build Example Drive connector skill"
    assert proposal.proposal.approval_mode == "skill"
    assert "Permission note" in proposal.proposal.summary
    assert "read access" in proposal.proposal.summary
    assert "does not grant write access by itself" in proposal.proposal.summary
    benefit = builder_proposal_acceptance_benefit(proposal.proposal)
    assert "may request read access" in benefit
    assert "does not grant write access by itself" in benefit
    assert "write-capable connector, explicit chat confirmation, and normal approval" in benefit
    assert proposal.context_key == "connector-skill:example-drive"


