def test_agent_request_tool_scope_widens_registry_before_retrying_turn() -> None:
    from nullion.agent_orchestrator import AgentOrchestrator
    from nullion.turn_context_policy import build_turn_tool_evidence, scoped_turn_tool_registry

    class Client:
        def __init__(self) -> None:
            self.tool_sets: list[set[str]] = []

        def create(self, **kwargs):
            self.tool_sets.append({tool["name"] for tool in (kwargs.get("tools") or [])})
            if len(self.tool_sets) == 1:
                return {
                    "stop_reason": "tool_use",
                    "content": [
                        {
                            "type": "tool_use",
                            "id": "scope-1",
                            "name": "request_tool_scope",
                            "input": {"capabilities": ["weather"]},
                        }
                    ],
                }
            assert "weather_forecast" in self.tool_sets[-1]
            return {
                "stop_reason": "tool_use",
                "content": [
                    {
                        "type": "tool_use",
                        "id": "weather-1",
                        "name": "weather_forecast",
                        "input": {"location": "10024"},
                    }
                ],
            } if len(self.tool_sets) == 2 else {"stop_reason": "end_turn", "content": [{"type": "text", "text": "Weather checked."}]}

    registry = ToolRegistry()
    registry.register(
        ToolSpec(
            name="weather_forecast",
            description="Get weather",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {"location": {"type": "string"}}, "required": ["location"]},
        ),
        lambda invocation: ToolResult(invocation.invocation_id, invocation.tool_name, "completed", {"summary": "Sunny"}),
    )
    scoped = scoped_turn_tool_registry(
        registry,
        evidence=build_turn_tool_evidence(user_message="weather", conversation_result=None),
        model_client=None,
        user_message="weather",
    )
    client = Client()
    activity: list[ToolResult] = []

    result = AgentOrchestrator(model_client=client).run_turn(
        conversation_id="telegram:scope",
        principal_id="telegram_chat",
        user_message="weather",
        conversation_history=[],
        tool_registry=scoped,
        policy_store=None,
        approval_store=None,
        tool_result_callback=activity.append,
    )

    assert client.tool_sets[0] == {"request_tool_scope"}
    assert "weather_forecast" in client.tool_sets[1]
    assert [tool.tool_name for tool in result.tool_results] == ["request_tool_scope", "weather_forecast"]
    assert activity[0].tool_name == "request_tool_scope"
    assert activity[0].status == "running"
    assert activity[0].output.get("suppress_activity") is True


