def test_sanitizer_never_replaces_complete_cron_inventory_with_partial_tool_message() -> None:
    crons = [
        {
            "selection_index": index,
            "name": name,
            "display_name": name,
            "enabled": True,
            "schedule_description": f"At {index}:00 PM every weekday",
            "next_run_description": f"Jul 14, 2026 at {index}:00 PM",
        }
        for index, name in enumerate(
            (
                "Email deadline triage",
                "Social traffic monitor",
                "Daily Pre-Market Stock Research",
                "Daily Post-Market Stock Report",
                "Mid-Market Stock Alert",
                "NYC Party Ticket Monitor",
                "Daily Weather",
                "Payment due reminder check",
            ),
            start=1,
        )
    ]
    full_reply = "Here are your 8 crons:\n\n" + "\n\n".join(
        (
            f"{cron['selection_index']}. {cron['name']}\n"
            "   Status: enabled\n"
            f"   Schedule: {cron['schedule_description']}\n"
            f"   Next run: {cron['next_run_description']}"
        )
        for cron in crons
    )
    partial_message = " ".join(full_reply.split())[:600]

    reply = sanitize_user_visible_reply(
        user_message="List all my crons",
        reply=full_reply,
        tool_results=[
            ToolResult(
                "cron-legacy-1",
                "list_crons",
                "completed",
                {
                    "cron_count": 8,
                    "crons": crons,
                    "message": partial_message,
                },
            )
        ],
    )

    assert len(reply or "") > len(partial_message)
    assert all(cron["name"] in (reply or "") for cron in crons)
    assert "8. Payment due reminder check" in (reply or "")
    assert "Next run: Jul 14, 2026 at 8:00 PM" in (reply or "")


