def test_sanitizer_preserves_scheduler_subset_reply() -> None:
    crons = [
        {"name": f"Scheduled item {index}", "selection_index": index}
        for index in range(1, 22)
    ]
    full_list = "Here are your 21 crons:\n\n" + "\n\n".join(
        f"{index}. Scheduled item {index}\nStatus: enabled"
        for index in range(1, 22)
    )
    subset_reply = "\n".join(
        [
            "I picked five random crons:",
            "1. Scheduled item 2",
            "2. Scheduled item 7",
            "3. Scheduled item 11",
            "4. Scheduled item 16",
            "5. Scheduled item 20",
        ]
    )

    reply = sanitize_user_visible_reply(
        user_message="Pick 5 random crons",
        reply=subset_reply,
        tool_results=[
            ToolResult(
                "list-1",
                "list_crons",
                "completed",
                {"message": full_list, "crons": crons},
            )
        ],
    )

    assert reply == subset_reply
    assert "Here are your 21 crons" not in reply
    assert "Scheduled item 21" not in reply


