def test_bulk_run_cron_receipt_mentions_background_delivery(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    from nullion import crons
    from nullion.tools import _build_run_cron_handler
    monkeypatch.setattr(crons, "_RUNTIME_DB_PATH", tmp_path / "runtime.db")
    monkeypatch.setattr("nullion.connections.workspace_id_for_principal", lambda principal: "workspace_admin")
    first = crons.add_cron(
        name="Morning report",
        schedule="0 8 * * *",
        task="Run the morning report.",
        workspace_id="workspace_admin",
    )
    second = crons.add_cron(
        name="Evening report",
        schedule="0 18 * * *",
        task="Run the evening report.",
        workspace_id="workspace_admin",
    )

    def runner(job):  # noqa: ANN001
        return {
            "cron_delivery_status": "deferred",
            "status_delivered": False,
            "text": f"Manual scheduled task run started: {job.name}.",
        }

    result = _build_run_cron_handler(runner)(
        ToolInvocation("bulk-run", "run_cron", "telegram:test-chat", {"all_enabled": True})
    )

    assert result.status == "completed"
    assert result.output["ids"] == [first.id, second.id]
    assert result.output["message"] == (
        "Started 2 cron runs. 2 background runs will deliver to the configured destinations when ready."
    )
    assert result.output["action_receipt"]["summary"] == result.output["message"]
    assert "Started: Morning report" in result.output["action_receipt"]["details"][0]
    assert all(item["delivery_status"] == "deferred" for item in result.output["results"])
    assert any(item.get("task_group_id") for item in result.output["results"])


def test_bulk_toggle_cron_updates_current_workspace_jobs(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    from nullion import crons
    from nullion.tools import _build_toggle_cron_handler

    monkeypatch.setattr(crons, "_RUNTIME_DB_PATH", tmp_path / "runtime.db")
    monkeypatch.setattr("nullion.connections.workspace_id_for_principal", lambda principal: "workspace_admin")
    first = crons.add_cron(
        name="Morning report",
        schedule="0 8 * * *",
        task="Run the morning report.",
        workspace_id="workspace_admin",
        enabled=False,
    )
    second = crons.add_cron(
        name="Evening report",
        schedule="0 18 * * *",
        task="Run the evening report.",
        workspace_id="workspace_admin",
        enabled=False,
    )
    other_workspace = crons.add_cron(
        name="Other workspace report",
        schedule="0 20 * * *",
        task="Run the other report.",
        workspace_id="workspace_other",
        enabled=False,
    )

    result = _build_toggle_cron_handler()(
        ToolInvocation(
            "bulk-toggle",
            "toggle_cron",
            "telegram:test-chat",
            {"all_current_workspace": True, "enabled": True},
        )
    )

    assert result.status == "completed"
    assert result.output["ids"] == [first.id, second.id]
    assert result.output["updated_count"] == 2
    assert result.output["message"] == "Enabled 2 cron jobs."
    assert crons.get_cron(first.id).enabled is True
    assert crons.get_cron(second.id).enabled is True
    assert crons.get_cron(other_workspace.id).enabled is False
    assert "Enabled: Morning report" in result.output["action_receipt"]["details"][0]


