def test_agent_retries_raw_tool_payload_final_response_before_sanitizer() -> None:
    from nullion.agent_orchestrator import AgentOrchestrator

    payload = {"messages": [{"subject": "Deadline", "due": "today"}]}

    class Client:
        def __init__(self) -> None:
            self.calls = 0
            self.prompts: list[str] = []

        def create(self, **kwargs):
            self.calls += 1
            messages = kwargs.get("messages") or []
            if messages:
                last = messages[-1].get("content") or []
                self.prompts.append("\n".join(block.get("text", "") for block in last if isinstance(block, dict)))
            if self.calls == 1:
                return {
                    "stop_reason": "tool_use",
                    "content": [
                        {
                            "type": "tool_use",
                            "id": "tu-1",
                            "name": "connector_request",
                            "input": {},
                        }
                    ],
                }
            if self.calls == 2:
                return {"stop_reason": "end_turn", "content": [{"type": "text", "text": str(payload)}]}
            return {
                "stop_reason": "end_turn",
                "content": [{"type": "text", "text": "One deadline-like email needs review today."}],
            }

    registry = ToolRegistry()
    registry.register(
        ToolSpec(
            name="connector_request",
            description="Call a connector",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {}},
        ),
        lambda invocation: ToolResult(invocation.invocation_id, invocation.tool_name, "completed", payload),
    )
    client = Client()

    result = AgentOrchestrator(model_client=client).run_turn(
        conversation_id="telegram:123",
        principal_id="telegram_chat",
        user_message="scheduled task",
        conversation_history=[],
        tool_registry=registry,
        policy_store=None,
        approval_store=None,
    )

    assert result.final_text == "One deadline-like email needs review today."
    assert result.raw_tool_payload_blocked is False
    assert any("raw structured tool payload" in prompt for prompt in client.prompts)


def test_agent_continues_after_web_search_non_answer_before_finalizing() -> None:
    from nullion.agent_orchestrator import AgentOrchestrator

    handler_calls: list[str] = []

    class Client:
        def __init__(self) -> None:
            self.calls = 0
            self.prompts: list[str] = []

        def create(self, **kwargs):
            self.calls += 1
            messages = kwargs.get("messages") or []
            if messages:
                last = messages[-1].get("content") or []
                self.prompts.append("\n".join(block.get("text", "") for block in last if isinstance(block, dict)))
            if self.calls == 1:
                return {
                    "stop_reason": "tool_use",
                    "content": [
                        {
                            "type": "tool_use",
                            "id": "search-1",
                            "name": "web_search",
                            "input": {"query": "best option"},
                        }
                    ],
                }
            if self.calls == 2:
                return {
                    "stop_reason": "end_turn",
                    "content": [
                        {
                            "type": "text",
                            "text": (
                                "I can give you search links, but I can't reliably read the live results. "
                                "Reply 1 and I'll narrow it down."
                            ),
                        }
                    ],
                }
            if self.calls == 3:
                return {
                    "stop_reason": "tool_use",
                    "content": [
                        {
                            "type": "tool_use",
                            "id": "read-1",
                            "name": "browser_extract_text",
                            "input": {"url": "https://records.example.test/a"},
                        }
                    ],
                }
            return {
                "stop_reason": "end_turn",
                "content": [
                    {
                        "type": "text",
                        "text": (
                            "Best match: Candidate A availability at records.example.test "
                            "is available from $37/day."
                        ),
                    }
                ],
            }

    registry = ToolRegistry()
    registry.register(
        ToolSpec(
            name="web_search",
            description="Search public webpages.",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {"query": {"type": "string"}}},
            continuation_tools=("browser_extract_text",),
        ),
        lambda invocation: (
            handler_calls.append("web_search")
            or ToolResult(
                invocation.invocation_id,
                invocation.tool_name,
                "completed",
                {
                    "results": [
                        {
                            "title": "Candidate A availability",
                            "url": "https://records.example.test/a",
                            "snippet": "Candidate A has current availability from $37/day.",
                        }
                    ]
                },
            )
        ),
    )
    registry.register(
        ToolSpec(
            name="browser_extract_text",
            description="Read a webpage.",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {"url": {"type": "string"}}},
        ),
        lambda invocation: (
            handler_calls.append("browser_extract_text")
            or ToolResult(
                invocation.invocation_id,
                invocation.tool_name,
                "completed",
                {"text": "Candidate A has current availability from $37/day."},
            )
        ),
    )
    client = Client()

    result = AgentOrchestrator(model_client=client).run_turn(
        conversation_id="telegram:123",
        principal_id="telegram_chat",
        user_message="Find the best available option.",
        conversation_history=[],
        tool_registry=registry,
        policy_store=None,
        approval_store=None,
    )

    assert handler_calls == ['web_search']
    assert result.final_text
    assert not any('discovery evidence only' in p for p in client.prompts)


