def test_agent_preserves_active_browser_form_flow_after_wait_timeout() -> None:
    from nullion.agent_orchestrator import AgentOrchestrator

    handler_calls: list[str] = []

    class Client:
        def __init__(self) -> None:
            self.calls = 0
            self.prompts: list[str] = []

        def create(self, **kwargs):
            self.calls += 1
            messages = kwargs.get("messages") or []
            if messages:
                last = messages[-1].get("content") or []
                self.prompts.append("\n".join(block.get("text", "") for block in last if isinstance(block, dict)))
            if self.calls == 1:
                return {
                    "stop_reason": "tool_use",
                    "content": [
                        {"type": "tool_use", "id": "type-1", "name": "browser_type_id", "input": {"element_id": "n-10", "text": "Providence, RI"}},
                        {"type": "tool_use", "id": "wait-1", "name": "browser_wait_for", "input": {"text": "quote results"}},
                    ],
                }
            if self.calls == 2:
                return {
                    "stop_reason": "tool_use",
                    "content": [
                        {"type": "tool_use", "id": "close-1", "name": "browser_close", "input": {}},
                    ],
                }
            if self.calls == 3:
                return {
                    "stop_reason": "tool_use",
                    "content": [
                        {
                            "type": "tool_use",
                            "id": "assert-1",
                            "name": "browser_assert_page_state",
                            "input": {"required": ["Current booking form", "Ready to continue"]},
                        },
                    ],
                }
            if self.calls == 4:
                return {
                    "stop_reason": "tool_use",
                    "content": [
                        {"type": "tool_use", "id": "detail-1", "name": "browser_extract_detail", "input": {}},
                    ],
                }
            return {
                "stop_reason": "end_turn",
                "content": [
                    {"type": "text", "text": "Verified result: the current form is still open and ready to continue."},
                ],
            }

    registry = ToolRegistry()
    registry.register(
        ToolSpec(
            name="browser_type_id",
            description="Type into a browser field.",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {}},
        ),
        lambda invocation: (
            handler_calls.append("browser_type_id")
            or ToolResult(invocation.invocation_id, invocation.tool_name, "completed", {"typed": 14})
        ),
    )
    registry.register(
        ToolSpec(
            name="browser_wait_for",
            description="Wait for browser state.",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {}},
        ),
        lambda invocation: (
            handler_calls.append("browser_wait_for")
            or ToolResult(invocation.invocation_id, invocation.tool_name, "failed", {}, "Timed out waiting for any browser condition.")
        ),
    )
    registry.register(
        ToolSpec(
            name="browser_close",
            description="Close browser.",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {}},
        ),
        lambda invocation: (
            handler_calls.append("browser_close")
            or ToolResult(invocation.invocation_id, invocation.tool_name, "completed", {"closed": "agent-browser-default"})
        ),
    )
    registry.register(
        ToolSpec(
            name="browser_assert_page_state",
            description="Verify current browser page.",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {}},
        ),
        lambda invocation: (
            handler_calls.append("browser_assert_page_state")
            or ToolResult(
                invocation.invocation_id,
                invocation.tool_name,
                "completed",
                _typed_evidence_page_assertion(
                    session_id="browser-session",
                    url="https://booking.example.test/form",
                    required=["Current booking form", "Ready to continue"],
                ),
            )
        ),
    )
    registry.register(
        ToolSpec(
            name="browser_extract_detail",
            description="Read current browser detail.",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {}},
        ),
        lambda invocation: (
            handler_calls.append("browser_extract_detail")
            or ToolResult(
                invocation.invocation_id,
                invocation.tool_name,
                "completed",
                _typed_dom_detail_output(
                    session_id="browser-session",
                    record={
                        "title": "Current booking form",
                        "url": "https://booking.example.test/form",
                        "availability": "Ready to continue",
                    },
                ),
            )
        ),
    )

    result = AgentOrchestrator(model_client=Client()).run_turn(
        conversation_id="telegram:123",
        principal_id="telegram_chat",
        user_message="Find a live booking result.",
        conversation_history=[],
        tool_registry=registry,
        policy_store=None,
        approval_store=None,
    )

    assert handler_calls == [
        "browser_type_id",
        "browser_wait_for",
        "browser_assert_page_state",
        "browser_extract_detail",
    ]
    assert [tool.tool_name for tool in result.tool_results] == [
        "browser_type_id",
        "browser_wait_for",
        "browser_close",
        "browser_assert_page_state",
        "browser_extract_detail",
    ]
    blocked_close = result.tool_results[2]
    assert blocked_close.status == "failed"
    assert blocked_close.output["reason"] == "active_browser_workflow_preserved"
    assert "current form is still open and ready to continue" in result.final_text
    assert "current form is still open and ready to continue" in result.final_text


