def test_agent_stops_after_raw_payload_cron_failure_without_reentering_connectors() -> None:
    from nullion.agent_orchestrator import AgentOrchestrator

    connector_payload = {
        "messages": [
            {
                "payload": {
                    "headers": [
                        {"name": "From", "value": "billing@example.test"},
                        {"name": "Subject", "value": "Account notice"},
                    ]
                },
                "snippet": "Review your account notice.",
            }
        ]
    }
    invoked_tools: list[str] = []

    class Client:
        def __init__(self) -> None:
            self.calls = 0

        def create(self, **kwargs):
            self.calls += 1
            if self.calls == 1:
                return {
                    "stop_reason": "tool_use",
                    "content": [
                        {
                            "type": "tool_use",
                            "id": "tu-run-cron",
                            "name": "run_cron",
                            "input": {"id": "c4cb766a"},
                        }
                    ],
                }
            return {
                "stop_reason": "tool_use",
                "content": [
                    {
                        "type": "tool_use",
                        "id": "tu-connector",
                        "name": "connector_request",
                        "input": {},
                    }
                ],
            }

    def run_cron_handler(invocation):
        invoked_tools.append(invocation.tool_name)
        return ToolResult(
            invocation.invocation_id,
            invocation.tool_name,
            "failed",
            {
                "id": "c4cb766a",
                "name": "Email deadline triage -- Maton Gmail",
                "reason": "cron_run_raw_tool_payload",
                "result_text": (
                    "Cron run was blocked because it produced raw structured tool output "
                    "instead of a deliverable report."
                ),
                "result": {"raw_tool_payload_blocked": True},
            },
            "Cron run produced raw structured tool output instead of a deliverable report.",
        )

    def connector_handler(invocation):
        invoked_tools.append(invocation.tool_name)
        return ToolResult(invocation.invocation_id, invocation.tool_name, "completed", connector_payload)

    registry = ToolRegistry()
    registry.register(
        ToolSpec(
            name="run_cron",
            description="Run a scheduled task by id",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.WRITE,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {"id": {"type": "string"}}},
        ),
        run_cron_handler,
    )
    registry.register(
        ToolSpec(
            name="connector_request",
            description="Call a connector",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.READ,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {}},
        ),
        connector_handler,
    )
    client = Client()

    result = AgentOrchestrator(model_client=client).run_turn(
        conversation_id="telegram:123",
        principal_id="telegram_chat",
        user_message="activar tarea",
        conversation_history=[],
        tool_registry=registry,
        policy_store=None,
        approval_store=None,
    )

    assert client.calls == 1
    assert invoked_tools == ["run_cron"]
    assert result.final_text is not None
    assert "delivery was blocked" in result.final_text
    assert "Email deadline triage -- Maton Gmail" in result.final_text
    assert "billing@example.test" not in result.final_text
    assert "Account notice" not in result.final_text
    assert result.tool_results[0].output["reason"] == "cron_run_raw_tool_payload"


