def test_sanitizer_preserves_email_answer_after_browser_lookup() -> None:
    results = [
        ToolResult(
            "search-1",
            "email_search",
            "completed",
            {
                "provider_id": "custom_connector_provider",
                "query": "in:inbox is:unread newer_than:1d",
                "results": [
                    {
                        "id": "msg-1",
                        "subject": "Your Thursday morning order with Uber Eats",
                        "from": "Uber Eats <orders@example.com>",
                        "snippet": "What's your phone number or email?",
                    }
                ],
                "body_requires_tool": "email_read",
                "next_tool_for_body": "email_read",
            },
        ),
        ToolResult(
            "read-1",
            "email_read",
            "completed",
            {
                "provider_id": "custom_connector_provider",
                "message": {
                    "id": "msg-1",
                    "subject": "Your Thursday morning order with Uber Eats",
                    "from": "Uber Eats <orders@example.com>",
                    "date": "Fri, 19 Jun 2026 08:00:00 +0000",
                    "body": "Your order receipt total was $12.34.",
                    "snippet": "Your order receipt total was $12.34.",
                },
            },
        ),
        ToolResult(
            "browser-1",
            "browser_extract_text",
            "completed",
            {
                "session_id": "agent-browser-default",
                "text": "What's your phone number or email?\nSign in to continue to Uber Eats orders.",
            },
        ),
    ]

    answer = "The receipt confirms a $12.34 order. I could not verify its current status because the order page requires sign-in."
    reply = sanitize_user_visible_reply(
        user_message="Open the second email from that list and check the order status.",
        reply=answer,
        tool_results=results,
    )
    assert answer in reply
    assert "Preview:" not in reply and "From:" not in reply
    assert "What's your phone number or email?" not in reply


