def test_browser_terminal_revalidation_context_matches_exact_amazon_trace() -> None:
    product_url = "https://www.amazon.com/dp/B06Y271G1K?th=1"
    product_title = "Kate Somerville EradiKate 3% Sulfur Daily Foaming Cleanser"
    required = [product_title, "$39.10", "In Stock"]
    results = [
        ToolResult(
            "product-detail",
            "browser_extract_detail",
            "completed",
            _typed_dom_detail_output(
                session_id="amazon-product-session",
                selector=None,
                record={
                    "title": product_title,
                    "url": product_url,
                    "price": "$39.10",
                    "availability": "In Stock",
                    "details": "ACTIVE INGREDIENT: Sulfur 3.0%; supplied as a foaming cleanser.",
                },
            ),
        ),
        ToolResult(
            "ingredient-read",
            "browser_run_js",
            "completed",
            {
                "session_id": "amazon-product-session",
                "result": {"important": "ACTIVE INGREDIENT: Sulfur 3.0%"},
            },
        ),
        ToolResult(
            "verified-product",
            "browser_assert_page_state",
            "completed",
            _typed_evidence_page_assertion(
                session_id="amazon-product-session",
                url=product_url,
                selector="body",
                required=required,
            ),
        ),
        ToolResult(
            "type-search",
            "browser_type_field",
            "completed",
            {
                "session_id": "amazon-product-session",
                "typed": 16,
                "target": {"label": "Search Amazon"},
            },
        ),
    ]

    context = browser_terminal_revalidation_context(results)

    assert context is not None
    assert context.session_id == "amazon-product-session"
    assert context.page_url == product_url
    assert context.selector == "body"
    assert context.required == tuple(required)
    assert context.forbidden == ()
    assert context.invalidating_invocation_id == "type-search"


