def test_browser_terminal_revalidation_contexts_fail_closed_after_sessionless_assertion() -> None:
    results: list[ToolResult] = []
    for suffix in ("a", "b"):
        session_id = f"session-{suffix}"
        product_url = f"https://shop.example.test/products/{suffix}"
        title = f"Product {suffix.upper()} liquid cleanser"
        results.extend(
            [
                ToolResult(
                    f"detail-{suffix}",
                    "browser_extract_detail",
                    "completed",
                    _typed_dom_detail_output(
                        session_id=session_id,
                        selector="#product",
                        record={
                            "title": title,
                            "url": product_url,
                            "price": "$19.00",
                        },
                    ),
                ),
                ToolResult(
                    f"verified-{suffix}",
                    "browser_assert_page_state",
                    "completed",
                    _typed_evidence_page_assertion(
                        session_id=session_id,
                        url=product_url,
                        selector="#product",
                        required=[title, "$19.00"],
                    ),
                ),
                ToolResult(
                    f"mutation-{suffix}",
                    "browser_type_field",
                    "completed",
                    {"session_id": session_id, "typed": 4},
                ),
            ]
        )
    sessionless_assertion = _typed_evidence_page_assertion(
        session_id="untrusted-placeholder",
        url="https://shop.example.test/results",
        required=["Unverified current product"],
        verified=False,
    )
    sessionless_assertion.pop("session_id")
    results.append(
        ToolResult(
            "newer-sessionless-failure",
            "browser_assert_page_state",
            "completed",
            sessionless_assertion,
        )
    )

    assert browser_terminal_revalidation_contexts(results) == ()


def test_browser_urls_share_exact_document_identity() -> None:
    assert browser_urls_share_document_identity(
        "HTTPS://Example.Test:443/catalog/item?variant=liquid#details",
        "https://example.test/catalog/item?variant=liquid#details",
    )
    assert not browser_urls_share_document_identity(
        "https://example.test/catalog/item?variant=liquid#details",
        "https://example.test/catalog/item?variant=bar#details",
    )
    assert not browser_urls_share_document_identity(
        "https://example.test/catalog/item?variant=liquid#details",
        "https://example.test/catalog/item?variant=liquid#reviews",
    )
    assert not browser_urls_share_document_identity("", "")


def _terminal_revalidation_detail_result(
    *,
    invocation_id: str,
    session_id: str,
    expected_url: str,
    observed_url: str,
    title: str,
    expected_session_id: str | None = None,
    expected_selector: str = "#product",
    observed_selector: str = "#product",
    forbidden: list[str] | None = None,
) -> ToolResult:
    required = [title, "$19.00"]
    forbidden = list(forbidden or [])
    output = _typed_dom_detail_output(
        session_id=session_id,
        selector=observed_selector,
        record={
            "title": title,
            "url": observed_url,
            "price": "$19.00",
        },
    )
    output["terminal_revalidation"] = {
        "page_url": expected_url,
        "selector": expected_selector,
        "session_id": expected_session_id or session_id,
        "required": required,
        "forbidden": forbidden,
        "invalidating_invocation_id": "prior-mutation",
    }
    output["page_state_assertion"] = _typed_evidence_page_assertion(
        session_id=session_id,
        url=observed_url,
        selector=observed_selector,
        required=required,
        forbidden=forbidden,
    )
    return ToolResult(
        invocation_id,
        "browser_extract_detail",
        "completed",
        output,
    )


