@pytest.mark.parametrize("downgraded_field", ["required", "forbidden"])
def test_terminal_revalidation_receipt_rejects_downgraded_assertion_contract(
    downgraded_field: str,
) -> None:
    session_id = "same-physical-session"
    product_url = "https://shop.example.test/products/a?variant=liquid"
    title = "Product A liquid cleanser"
    terminal_result = _terminal_revalidation_detail_result(
        invocation_id=f"terminal-detail-downgraded-{downgraded_field}",
        session_id=session_id,
        expected_url=product_url,
        observed_url=product_url,
        title=title,
        forbidden=["bar version"],
    )
    terminal_output = terminal_result.output
    assert isinstance(terminal_output, dict)
    embedded_assertion = terminal_output.get("page_state_assertion")
    assert isinstance(embedded_assertion, dict)
    assertion_contract = embedded_assertion.get("contract")
    assertion_state = embedded_assertion.get("result")
    assert isinstance(assertion_contract, dict)
    assert isinstance(assertion_state, dict)
    if downgraded_field == "required":
        assertion_contract["required"] = [title]
        assertion_state["required"] = [{"expected": title, "match": title}]
    else:
        assertion_contract["forbidden"] = []
        assertion_state["forbidden"] = []
    results = [
        ToolResult(
            "pre-assert-a",
            "browser_assert_page_state",
            "completed",
            _typed_evidence_page_assertion(
                session_id=session_id,
                url=product_url,
                selector="#product",
                required=[title, "$19.00"],
                forbidden=["bar version"],
            ),
        ),
        terminal_result,
    ]

    assert not browser_terminal_revalidation_result_is_verified(
        results,
        invocation_id=terminal_result.invocation_id,
    )


