@pytest.mark.parametrize(
    ("required_date", "visible_date"),
    [
        ("5. Juli 2026", "2026-07-05"),
        ("2026-07-05", "5. Juli 2026"),
    ],
)
@pytest.mark.parametrize(
    "producer_tool",
    ["browser_extract_detail", "browser_extract_items"],
)
def test_browser_answer_preservation_binds_browser_verified_localized_date_aliases(
    required_date: str,
    visible_date: str,
    producer_tool: str,
) -> None:
    appointment_url = "https://appointments.example.test/current"
    title = "Biometrics appointment"
    record = {
        "title": title,
        "url": appointment_url,
        "details": f"Appointment date: {visible_date}",
    }
    producer_output = (
        _typed_dom_detail_output(
            session_id="localized-date-session",
            selector="#appointment",
            record=record,
        )
        if producer_tool == "browser_extract_detail"
        else {
            "session_id": "localized-date-session",
            "items": [record],
        }
    )
    results = [
        ToolResult(
            "verified-appointment",
            "browser_assert_page_state",
            "completed",
            _typed_evidence_page_assertion(
                session_id="localized-date-session",
                url=appointment_url,
                selector="#appointment",
                required=[title, required_date],
                matches=[title, visible_date],
            ),
        ),
        ToolResult(
            "appointment-detail",
            producer_tool,
            "completed",
            producer_output,
        ),
    ]

    draft_reply = ("Live-search blocker: no verified result records were available.")
    reply = sanitize_user_visible_reply(
        user_message="Show the verified appointment details.",
        reply="Live-search blocker: no verified result records were available.",
        tool_results=results,
    )

    assert reply == sanitize_user_visible_reply(user_message=None, reply=draft_reply, tool_results=[])


