def _sanitize_structural_price_record(
    *,
    current_price: str,
    rejected_observations: list[dict[str, object]],
    details: str,
) -> tuple[str, str]:
    product_url = "https://shop.example.test/products/sulfur-cleanser"
    title = "Liquid sulfur cleanser"
    assertion = _typed_evidence_page_assertion(
        session_id="price-session",
        url=product_url,
        selector="#product",
        required=[title, current_price],
    )
    record = {
        "title": title,
        "url": product_url,
        "price": current_price,
        "details": details,
        "price_observations": [
            {
                "value": current_price,
                "status": "current_candidate",
                "reasons": [],
            },
            *rejected_observations,
        ],
    }
    reply = sanitize_user_visible_reply(
        user_message="Find the current liquid sulfur cleanser and its price.",
        reply=f"{title}: {current_price}",
        tool_results=[
            ToolResult(
                "price-verified",
                "browser_assert_page_state",
                "completed",
                assertion,
            ),
            ToolResult(
                "price-detail",
                "browser_extract_detail",
                "completed",
                _typed_dom_detail_output(
                    session_id="price-session",
                    selector="#product",
                    record=record,
                ),
            ),
        ],
    )
    assert reply is not None
    return reply, _browser_record_text_without_suppressed_prices(record, details)


def test_sanitizer_never_renders_structurally_rejected_prices_from_detail_prose() -> None:
    reply, cleaned_details = _sanitize_structural_price_record(
        current_price="$19.99",
        rejected_observations=[
            {"value": "$77.00", "status": "rejected", "reasons": ["distinct_record_island"]},
            {"value": "$31.00", "status": "rejected", "reasons": ["explicitly_unselected_offer"]},
            {"value": "$1.90", "status": "superseded_role", "reasons": []},
            {"value": "$29.00", "status": "rejected", "reasons": ["struck_or_list_value"]},
            {"value": "5", "status": "superseded_role", "reasons": []},
        ],
        details=(
            "Contains 5% sulfur. Related $77.00. Alternate $31.00. "
            "Installment $1.90. Previous $29.00."
        ),
    )

    assert "$19.99" in reply
    assert "5% sulfur" in cleaned_details
    for rejected in ("$77.00", "$31.00", "$1.90", "$29.00"):
        assert rejected not in reply
        assert rejected not in cleaned_details
    assert "Live-search blocker" not in reply


