def _with_runtime_dom_detail_provenance(
    results: list[ToolResult],
) -> list[ToolResult]:
    """Upgrade legacy positive fixtures to the fixed DOM producer contract.

    The production sanitizer must never trust an arbitrary ``browser_run_js``
    mapping. Tests that exercise verified detail synthesis use this helper to
    represent the independent, runtime-owned extraction that BrowserTools now
    performs. Raw-JavaScript rejection and mutation tests intentionally do not
    call this helper.
    """

    normalized: list[ToolResult] = []
    for result in results:
        output = dict(result.output or {})
        if result.tool_name.startswith("browser_") and not output.get("session_id"):
            output["session_id"] = "fixture-browser-session"
        normalized.append(
            ToolResult(
                result.invocation_id,
                result.tool_name,
                result.status,
                output,
                result.error,
            )
        )

    converted: list[ToolResult] = []
    for result in normalized:
        output = dict(result.output or {})
        raw_record = output.get("result")
        if not isinstance(raw_record, dict):
            raw_records = output.get("records")
            raw_record = (
                raw_records[0]
                if isinstance(raw_records, list)
                and len(raw_records) == 1
                and isinstance(raw_records[0], dict)
                else None
            )
        if result.tool_name != "browser_run_js" or not isinstance(raw_record, dict):
            converted.append(result)
            continue

        record = dict(raw_record)
        if not record.get("title"):
            for key in ("productTitle", "name", "label"):
                if record.get(key):
                    record["title"] = record[key]
                    break
        if not record.get("url"):
            for key in ("href", "action_url", "product_url", "productUrl", "link"):
                if record.get(key):
                    record["url"] = record[key]
                    break
        if not record.get("title") or not record.get("url"):
            converted.append(result)
            continue

        session_id = str(output["session_id"])
        selector = None
        embedded_assertion = output.get("page_state_assertion")
        if isinstance(embedded_assertion, dict):
            embedded_page = embedded_assertion.get("result")
            embedded_contract = embedded_assertion.get("contract")
            if isinstance(embedded_contract, dict):
                selector = embedded_contract.get("selector")
            if selector is None and isinstance(embedded_page, dict):
                selector = embedded_page.get("selector")
        for assertion_result in reversed(normalized):
            if assertion_result.tool_name != "browser_assert_page_state":
                continue
            assertion_output = dict(assertion_result.output or {})
            if str(assertion_output.get("session_id") or "") != session_id:
                continue
            assertion = assertion_output.get("page_state_assertion")
            if not isinstance(assertion, dict):
                assertion = assertion_output
            assertion_page = assertion.get("result")
            if not isinstance(assertion_page, dict):
                continue
            if assertion_page.get("url") and assertion_page.get("url") != record["url"]:
                continue
            contract = assertion.get("contract")
            selector = (
                contract.get("selector")
                if isinstance(contract, dict)
                else assertion_page.get("selector")
            )
            if selector is None:
                selector = assertion_page.get("selector")
            break

        if isinstance(embedded_assertion, dict):
            assertion_output = dict(embedded_assertion)
            assertion_output.setdefault("session_id", session_id)
            converted.append(
                ToolResult(
                    f"{result.invocation_id}-page-state",
                    "browser_assert_page_state",
                    result.status,
                    assertion_output,
                    result.error,
                )
            )
        converted.append(
            ToolResult(
                result.invocation_id,
                "browser_extract_detail",
                result.status,
                _typed_dom_detail_output(
                    session_id=session_id,
                    selector=selector if isinstance(selector, str) else None,
                    record=record,
                ),
                result.error,
            )
        )
    return converted


class _RuntimeOwnedDomDetailFixture:
    """List-like fixture syntax for verified runtime DOM detail scenarios."""

    def __getitem__(self, results: ToolResult | tuple[ToolResult, ...]) -> list[ToolResult]:
        values = list(results) if isinstance(results, tuple) else [results]
        return _with_runtime_dom_detail_provenance(values)


_runtime_owned_dom_details = _RuntimeOwnedDomDetailFixture()


def test_browser_answer_preservation_rejects_literal_browser_run_js_record_even_with_verified_page() -> None:
    product_url = "https://shop.example.test/products/current"
    draft_reply = (f"Synthesized Product — $1.00\nOpen: {product_url}")
    reply = sanitize_user_visible_reply(
        user_message="Find the current product.",
        reply=f"Synthesized Product — $1.00\nOpen: {product_url}",
        tool_results=[
            ToolResult(
                "verified",
                "browser_assert_page_state",
                "completed",
                {
                    "session_id": "browser-session",
                    "verified": True,
                    "result": {
                        "ok": True,
                        "url": product_url,
                        "selector": "#product",
                        "required": [
                            {"expected": "Synthesized Product", "match": "Synthesized Product"}
                        ],
                        "forbidden": [],
                        "missing": [],
                        "forbidden_found": [],
                    },
                },
            ),
            ToolResult(
                "literal-js",
                "browser_run_js",
                "completed",
                {
                    "session_id": "browser-session",
                    "result": {
                        "title": "Synthesized Product",
                        "url": product_url,
                        "price": "$1.00",
                        "details": "A literal mapping not read by the runtime DOM extractor.",
                    },
                },
            ),
        ],
    )

