def test_browser_answer_preservation_invalidates_stale_detail_after_failed_partial_browser_mutation() -> None:
    from nullion.plugins.browser_plugin.browser_policy import BrowserPolicy
    from nullion.plugins.browser_plugin.browser_session import BrowserSessionPool
    from nullion.plugins.browser_plugin.browser_tools import BrowserTools

    class PartialMutationBackend:
        BACKEND_NAME = "fake"

        async def run_js(self, session_id: str, script: str):  # noqa: ANN001
            raise RuntimeError("JavaScript changed the DOM before throwing")

    product_url = "https://shop.example.test/products/current"
    stale_record = {
        "title": "Product One",
        "url": product_url,
        "price": "$10",
        "details": "Product One original detail.",
    }
    failed_mutation = BrowserTools(
        backend=PartialMutationBackend(),
        pool=BrowserSessionPool(),
        policy=BrowserPolicy(),
    ).browser_run_js(
        ToolInvocation(
            "partial-mutation",
            "browser_run_js",
            "operator",
            {"script": "document.body.dataset.changed = 'yes'; throw new Error('boom')"},
            capsule_id="turn-partial-mutation",
            flow_context={"browser_session_id": "browser-session"},
        )
    )

    draft_reply = (f"Product One — $10\nOpen: {product_url}")
    reply = sanitize_user_visible_reply(
        user_message="What is the current price of Product One?",
        reply=f"Product One — $10\nOpen: {product_url}",
        tool_results=[
            ToolResult(
                "verified-before",
                "browser_assert_page_state",
                "completed",
                {
                    "session_id": "browser-session",
                    "verified": True,
                    "result": {
                        "ok": True,
                        "url": product_url,
                        "selector": "#product",
                        "required": [{"expected": "Product One", "match": "Product One"}],
                        "forbidden": [],
                        "missing": [],
                        "forbidden_found": [],
                    },
                },
            ),
            ToolResult(
                "detail-before",
                "browser_extract_detail",
                "completed",
                _typed_dom_detail_output(
                    session_id="browser-session",
                    selector="#product",
                    record=stale_record,
                ),
            ),
            failed_mutation,
        ],
    )

    assert reply == sanitize_user_visible_reply(user_message=None, reply=draft_reply, tool_results=[])


def test_browser_answer_preservation_prefers_verified_detail_after_same_document_anchor_click_over_stale_rows() -> None:
    product_url = (
        "https://www.amazon.com/DermaHarmony-Sulfur-Salicylic-Liquid-Castile/"
        "dp/B0897CFK16?th=1"
    )
    anchored_url = f"{product_url}#skippedLink"
    product_title = (
        "Dermaharmony 5% Sulfur and 2% Salicylic Acid Liquid Castile Soap "
        "(4 Fl Oz Bottle)"
    )
    session_id = "agent-browser-default"
    stale_preview = json.dumps(
        {
            "action_receipt": {
                "type": "action_receipt",
                "action": "browser_run_js",
                "summary": "Completed action: browser_run_js.",
            },
            "result": [
                {
                    "title": "Jericho Dead Sea Sulfur Soap - Vegan Face & Body Bar",
                    "price": "$8.99",
                    "url": "https://www.amazon.com/dp/JERICHO-BAR",
                },
                {
                    "title": "VALITIC Kojic Acid Dark Spot Remover Soap Bars",
                    "price": "$14.99",
                    "url": "https://www.amazon.com/dp/VALITIC-BARS-ONE",
                },
                {
                    "title": "VALITIC Kojic Acid Dark Spot Remover Soap Bars",
                    "price": "$19.99",
                    "url": "https://www.amazon.com/dp/VALITIC-BARS-TWO",
                },
                {
                    "title": "Bee & Flower Sulfur Soap Liquid Shampoo & Body Wash",
                    "price": "$14.59",
                    "url": "https://www.amazon.com/dp/BEE-FLOWER-LIQUID",
                },
            ],
        }
    )
    stale_preview = stale_preview[:-2] + ', {"title": "incomplete transport record"'

    draft_reply = ("Most relevant public-source results I could verify\n\n"
            "1. Jericho Dead Sea Sulfur Soap - Vegan Face & Body Bar\n\n"
            "2. VALITIC Kojic Acid Dark Spot Remover Soap Bars\n\n"
            "3. VALITIC Kojic Acid Dark Spot Remover Soap Bars\n\n"
            "4. Bee & Flower Sulfur Soap Liquid Shampoo & Body Wash")
    reply = sanitize_user_visible_reply(
        user_message="Can you find me a non-bar sulfur soap that actually has sulfur on amazon?",
        reply=(
            "Most relevant public-source results I could verify\n\n"
            "1. Jericho Dead Sea Sulfur Soap - Vegan Face & Body Bar\n\n"
            "2. VALITIC Kojic Acid Dark Spot Remover Soap Bars\n\n"
            "3. VALITIC Kojic Acid Dark Spot Remover Soap Bars\n\n"
            "4. Bee & Flower Sulfur Soap Liquid Shampoo & Body Wash"
        ),
        tool_results=[
            ToolResult(
                "navigate-product",
                "browser_navigate",
                "completed",
                {
                    "session_id": session_id,
                    "result": f"Navigated to {product_url} (status 200)",
                },
            ),
            ToolResult(
                "stale-results",
                "browser_run_js",
                "completed",
                {
                    "original_chars": len(stale_preview) + 9000,
                    "preview": stale_preview,
                    "truncated": True,
                },
            ),
            ToolResult(
                "initial-detail",
                "browser_run_js",
                "completed",
                {
                    "session_id": session_id,
                    "result": {
                        "text": product_title,
                        "title": product_title,
                        "url": product_url,
                    },
                },
            ),
            ToolResult(
                "assert-broad",
                "browser_assert_page_state",
                "completed",
                {
                    "session_id": session_id,
                    "verified": False,
                    "result": {
                        "ok": False,
                        "url": product_url,
                        "selector": "body",
                        "forbidden_found": [
                            {"expected": "Bar", "match": "Compare with similar bar products"}
                        ],
                    },
                },
            ),
            ToolResult(
                "assert-scoped",
                "browser_assert_page_state",
                "completed",
                {
                    "session_id": session_id,
                    "verified": True,
                    "result": {
                        "ok": True,
                        "url": product_url,
                        "selector": "#titleSection",
                        "required": [
                            {"expected": product_title, "match": product_title},
                            {"expected": "5% Sulfur", "match": product_title},
                        ],
                        "forbidden": [
                            {"expected": "Bar", "match": ""},
                            {"expected": "Soap Bar", "match": ""},
                        ],
                        "missing": [],
                        "forbidden_found": [],
                    },
                },
            ),
            ToolResult(
                "snapshot",
                "browser_snapshot",
                "completed",
                {
                    "session_id": session_id,
                    "url": product_url,
                    "elements": [{"role": "link", "name": "Main content"}],
                },
            ),
            ToolResult(
                "anchor-click",
                "browser_click_element",
                "completed",
                {
                    "session_id": session_id,
                    "clicked": {"role": "link", "name": "Main content"},
                    "action_receipt": {
                        "type": "action_receipt",
                        "action": "browser_click_element",
                        "summary": "Completed action: browser_click_element.",
                    },
                },
            ),
            ToolResult(
                "final-detail",
                "browser_extract_detail",
                "completed",
                {
                    **_typed_dom_detail_output(
                        session_id=session_id,
                        selector="#centerCol",
                        page_title=f"Amazon.com : {product_title} : Beauty & Personal Care",
                        record={
                        "availability": "In Stock",
                        "price": "$9.99",
                        "title": product_title,
                        "details": "5% sulfur liquid Castile soap in a 4 fl oz bottle.",
                        "url": anchored_url,
                        },
                    ),
                    "page_state_assertion": _typed_evidence_page_assertion(
                        session_id=session_id,
                        url=anchored_url,
                        required=[product_title, "5% Sulfur"],
                        forbidden=["Bar", "Soap Bar"],
                        selector="#centerCol",
                    ),
                },
            ),
        ],
    )

    assert reply == sanitize_user_visible_reply(user_message=None, reply=draft_reply, tool_results=[])


