def test_sanitizer_keeps_verified_session_when_other_session_later_fails_state() -> None:
    verified_url = "https://shop.example.test/product/one"
    other_url = "https://shop.example.test/product/two"
    reply = sanitize_user_visible_reply(
        user_message="Find Product One.",
        reply=f"Product One — $12\nOpen: {verified_url}",
        tool_results=_runtime_owned_dom_details[
            ToolResult(
                "verified-detail",
                "browser_run_js",
                "completed",
                {
                    "session_id": "session-a",
                    "result": {"title": "Product One", "url": verified_url, "price": "$12"},
                },
            ),
            ToolResult(
                "verified-state",
                "browser_assert_page_state",
                "completed",
                {
                    "session_id": "session-a",
                    "verified": True,
                    "result": {
                        "ok": True,
                        "url": verified_url,
                        "required": [{"expected": "Product One", "match": "Product One"}],
                        "forbidden": [],
                    },
                },
            ),
            ToolResult(
                "other-detail",
                "browser_run_js",
                "completed",
                {
                    "session_id": "session-b",
                    "result": {"title": "Product Two", "url": other_url, "price": "$99"},
                },
            ),
            ToolResult(
                "failed-other-state",
                "browser_assert_page_state",
                "completed",
                {
                    "session_id": "session-b",
                    "verified": False,
                    "result": {
                        "ok": False,
                        "url": other_url,
                        "required": [{"expected": "Requested Product", "match": ""}],
                        "forbidden": [],
                        "missing": [{"expected": "Requested Product", "match": ""}],
                    },
                },
            ),
        ],
    )

    assert reply is not None
    assert "Live-search blocker" not in reply
    assert "Product One" in reply
    assert "$12" in reply
    assert "Product Two" not in reply
    assert "$99" not in reply


