def test_browser_answer_preservation_preserves_all_outcomes_with_terminal_browser_write_receipt(
    tmp_path: Path,
) -> None:
    from nullion.runtime import bootstrap_persistent_runtime
    from nullion.tools import ToolExecutor

    registry = ToolRegistry(filesystem_allowed_roots=[tmp_path])
    registry.register(
        ToolSpec(
            name="browser_click_element",
            description="Click the selected browser element.",
            risk_level=ToolRiskLevel.LOW,
            side_effect_class=ToolSideEffectClass.WRITE,
            requires_approval=False,
            timeout_seconds=5,
            input_schema={"type": "object", "properties": {}},
        ),
        lambda invocation: ToolResult(
            invocation.invocation_id,
            invocation.tool_name,
            "completed",
            {"session_id": "browser-session-b", "message": "Opened details."},
        ),
    )
    runtime = bootstrap_persistent_runtime(tmp_path / "runtime.db")
    click_result = ToolExecutor(store=runtime.store, registry=registry).invoke(
        ToolInvocation("click", "browser_click_element", "web:test", {})
    )

    artifact_path = tmp_path / "price-report.csv"
    artifact_path.write_text("product,price\nProduct One,$12\n", encoding="utf-8")
    product_url = "https://shop.example.test/product/one"
    draft_reply = (f"Product One — $12\nOpen: {product_url}\n\n"
            "Cron created: Price monitor.\n\nOpened details.")
    reply = sanitize_user_visible_reply(
        user_message="Find Product One, create a monitor, and save the report.",
        reply=(
            f"Product One — $12\nOpen: {product_url}\n\n"
            "Cron created: Price monitor.\n\nOpened details."
        ),
        tool_results=_runtime_owned_dom_details[
            ToolResult(
                "product-detail",
                "browser_run_js",
                "completed",
                {
                    "session_id": "browser-session-a",
                    "result": {"title": "Product One", "url": product_url, "price": "$12"},
                },
            ),
            ToolResult(
                "verified-product",
                "browser_assert_page_state",
                "completed",
                {
                    "session_id": "browser-session-a",
                    "verified": True,
                    "result": {
                        "ok": True,
                        "url": product_url,
                        "required": [{"expected": "Product One", "match": "Product One"}],
                        "forbidden": [],
                    },
                },
            ),
            ToolResult(
                "create-monitor",
                "create_cron",
                "completed",
                {
                    "message": "Cron created: Price monitor.",
                    "action_receipt": {
                        "type": "action_receipt",
                        "action": "create_cron",
                        "summary": "Cron created: Price monitor.",
                    },
                },
            ),
            ToolResult(
                "scope",
                "request_tool_scope",
                "completed",
                {"requested_artifact_extensions": [".csv"]},
            ),
            ToolResult(
                "report",
                "file_write",
                "completed",
                {"artifact_path": str(artifact_path)},
            ),
            click_result,
        ],
    )

    assert reply == sanitize_user_visible_reply(user_message=None, reply=draft_reply, tool_results=[])


