@pytest.mark.parametrize(
    "invalid_case",
    [
        "version",
        "session",
        "verified_mismatch",
        "contract_mismatch",
        "missing_url",
        "empty_required_match",
        "forbidden_match",
        "missing_inconsistent",
        "forbidden_found_inconsistent",
    ],
)
def test_browser_answer_preservation_rejects_invalid_typed_page_assertion_envelopes(invalid_case: str) -> None:
    base_url = "https://app.example.test/product/blue"
    current_url = f"{base_url}#details"
    payload = _typed_evidence_page_assertion(
        session_id="browser-session",
        url=current_url,
        required=["Blue model"],
        forbidden=["Red model"],
    )
    if invalid_case == "version":
        payload["schema_version"] = True
    elif invalid_case == "session":
        payload["session_id"] = "another-session"
    elif invalid_case == "verified_mismatch":
        payload["verified"] = False
    elif invalid_case == "contract_mismatch":
        payload["contract"]["required"] = ["Different model"]
    elif invalid_case == "missing_url":
        payload["result"]["url"] = ""
    elif invalid_case == "empty_required_match":
        payload["result"]["required"][0]["match"] = ""
    elif invalid_case == "forbidden_match":
        payload["result"]["forbidden"][0]["match"] = "Red model"
    elif invalid_case == "missing_inconsistent":
        payload["result"]["missing"] = [{"expected": "Blue model", "match": ""}]
    elif invalid_case == "forbidden_found_inconsistent":
        payload["result"]["forbidden_found"] = [
            {"expected": "Red model", "match": "Red model"}
        ]

    draft_reply = (f"Blue model — $10\nOpen: {current_url}")
    reply = sanitize_user_visible_reply(
        user_message="Find the verified model.",
        reply=f"Blue model — $10\nOpen: {current_url}",
        tool_results=[
            ToolResult(
                "verified-blue",
                "browser_assert_page_state",
                "completed",
                {
                    "session_id": "browser-session",
                    "verified": True,
                    "result": {
                        "ok": True,
                        "url": base_url,
                        "required": [{"expected": "Blue model", "match": "Blue model"}],
                        "forbidden": [{"expected": "Red model", "match": ""}],
                    },
                },
            ),
            ToolResult(
                "route-click",
                "browser_click_element",
                "completed",
                {"session_id": "browser-session", "clicked": {"role": "link", "name": "Details"}},
            ),
            ToolResult(
                "current-detail",
                "browser_run_js",
                "completed",
                {
                    "session_id": "browser-session",
                    "result": {"title": "Blue model", "url": current_url, "price": "$10"},
                    "page_state_assertion": payload,
                },
            ),
        ],
    )

    assert reply == sanitize_user_visible_reply(user_message=None, reply=draft_reply, tool_results=[])


