@pytest.mark.parametrize(
    ("reply_text", "receipt_overrides"),
    [
        ("Error: Added Product One to cart. was not completed.", {}),
        ("Added Product One to cart.", {"foreground_reply_suppressed": True}),
        ("Added Product One to cart.", {"receipt_action": "browser_type"}),
    ],
)
def test_browser_answer_preservation_rejects_untrusted_terminal_browser_receipt_match(
    reply_text: str,
    receipt_overrides: dict[str, object],
) -> None:
    action = str(receipt_overrides.get("receipt_action") or "browser_click_element")
    output = {
        "action_receipt": {
            "type": "action_receipt",
            "action": action,
            "summary": "Added Product One to cart.",
        },
        **{
            key: value
            for key, value in receipt_overrides.items()
            if key != "receipt_action"
        },
    }
    draft_reply = (reply_text)
    reply = sanitize_user_visible_reply(
        user_message="Add Product One to my cart.",
        reply=reply_text,
        tool_results=[
            ToolResult(
                "terminal-browser-action",
                "browser_click_element",
                "completed",
                output,
            )
        ],
    )

    assert reply == sanitize_user_visible_reply(user_message=None, reply=draft_reply, tool_results=[])


