def test_structured_sections_keep_runtime_dom_supplemental_evidence_after_assertion() -> None:
    product_url = "https://shop.example.test/product/one"
    results = [
        ToolResult(
            "verified-product",
            "browser_assert_page_state",
            "completed",
            {
                "session_id": "browser-session",
                "verified": True,
                "result": {
                    "ok": True,
                    "url": product_url,
                    "required": [{"expected": "Product One", "match": "Product One"}],
                },
            },
        ),
        ToolResult(
            "product-detail",
            "browser_extract_detail",
            "completed",
            _typed_dom_detail_output(
                session_id="browser-session",
                record={
                    "title": "Product One",
                    "url": product_url,
                    "price": "$12",
                    "details": (
                        "Product One current listing. Pickup availability: "
                        "Available today, Downtown."
                    ),
                },
            ),
        ),
    ]

    sections = _structured_tool_evidence_sections(
        results,
        user_message="Find Product One and its pickup availability.",
        prefer_browser_source_heading=True,
    )
    rendered = "\n".join(line for _heading, lines, _items in sections for line in lines)

    assert "Product One" in rendered
    assert "$12" in rendered
    assert "Pickup availability" in rendered
    assert "Available today" in rendered


